DECLARE result text;
BEGIN
  CASE jsonb_typeof(j)
  WHEN 'object' THEN
    SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||public.qualification_native_canonical_v55(value),',' ORDER BY key COLLATE "C"),'')||'}'
      INTO result FROM jsonb_each(j);
  WHEN 'array' THEN
    SELECT '['||coalesce(string_agg(public.qualification_native_canonical_v55(value),',' ORDER BY ord),'')||']'
      INTO result FROM jsonb_array_elements(j) WITH ORDINALITY x(value,ord);
  WHEN 'string' THEN
    IF NOT ((j#>>'{}') COLLATE "C" ~ '^[ -~]*$') THEN RAISE EXCEPTION 'native_filled_canonical_ascii'; END IF;
    result := j::text;
  WHEN 'number' THEN
    IF j::text !~ '^-?(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'native_filled_canonical_integer'; END IF;
    result := j::text;
  ELSE result := j::text;
  END CASE;
  RETURN result;
END;

DECLARE s record;
BEGIN
  SELECT * INTO s FROM public.qualification_report_spool WHERE spool_id=sid;
  RETURN coalesce(s.spool_id IS NOT NULL AND s.eligible IS TRUE AND s.report_sha256=report_sha
    AND s.policy_sha256=policy_sha AND s.queue_namespace=namespace AND verified_at>=s.created_at
    AND public.qualification_native_report_eligible_v55(s.outcome_id,s.reservation_id,report_sha,policy_sha),false);
END;

