  IF ROW(NEW.environment,NEW.account_id,NEW.settlement_currency) IS DISTINCT FROM
     ROW(OLD.environment,OLD.account_id,OLD.settlement_currency)
     OR NEW.ledger_revision <> OLD.ledger_revision + 1
     OR NEW.account_revision NOT IN (OLD.account_revision,OLD.account_revision + 1)
     OR (OLD.ledger_revision > 0 AND NEW.updated_at < OLD.updated_at)
     OR ((ROW(NEW.claims_json,NEW.claims_sha256) IS DISTINCT FROM ROW(OLD.claims_json,OLD.claims_sha256))
         <> (NEW.account_revision = OLD.account_revision + 1)) THEN
    RAISE EXCEPTION 'qualification_scope_update_denied';
  END IF;
  RETURN NEW;
END;

DECLARE o RECORD; r RECORD; j JSONB;
BEGIN
  IF NEW.eligible IS TRUE THEN
    SELECT * INTO o FROM public.qualification_submission_outcomes WHERE outcome_id=NEW.outcome_id;
    SELECT * INTO r FROM public.qualification_reservations WHERE reservation_id=NEW.reservation_id;
    j := public.qualification_native_plain_v55(o.capture_json);
    IF r.report_id IS DISTINCT FROM NEW.report_id OR NEW.created_at IS DISTINCT FROM o.recorded_at
       OR encode(sha256(NEW.report_bytes),'hex') IS DISTINCT FROM NEW.report_sha256
       OR encode(sha256(convert_to(NEW.policy_json,'UTF8')),'hex') IS DISTINCT FROM NEW.policy_sha256
       OR NOT public.qualification_native_report_eligible_v55(NEW.outcome_id,NEW.reservation_id,NEW.report_sha256,NEW.policy_sha256)
       OR NEW.report_bytes IS DISTINCT FROM convert_to((SELECT capture_json::jsonb->>'forensics_json'
         FROM public.qualification_submission_outcomes WHERE outcome_id=j->>'forensics_outcome_id'),'UTF8') THEN
      RAISE EXCEPTION 'native_terminal_spool_denied';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO o FROM public.qualification_submission_outcomes
    WHERE outcome_id=NEW.outcome_id;
  SELECT * INTO r FROM public.qualification_reservations
    WHERE reservation_id=NEW.reservation_id;
  IF o.outcome_id IS NULL OR r.reservation_id IS NULL
    OR o.reservation_id IS DISTINCT FROM NEW.reservation_id
    OR r.report_id IS DISTINCT FROM NEW.report_id
    OR NEW.created_at IS DISTINCT FROM o.recorded_at THEN
    RAISE EXCEPTION 'submission_spool_binding_denied';
  END IF;
  BEGIN
    j := o.outcome_json::jsonb;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'submission_spool_transport_evidence_invalid';
  END;
  IF jsonb_typeof(j) IS DISTINCT FROM 'object'
    OR j->>'status' IS DISTINCT FROM o.status
    OR j->'transport_authenticity_verified' IS DISTINCT FROM 'false'::jsonb
    OR NEW.eligible IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'submission_spool_transport_unverified';
  END IF;
  RETURN NEW;
END;

DECLARE s record;
BEGIN
  SELECT * INTO s FROM public.qualification_report_spool WHERE spool_id=NEW.spool_id;
  IF s.spool_id IS NOT NULL AND s.eligible IS TRUE AND NEW.report_sha256=s.report_sha256
     AND NEW.policy_sha256=s.policy_sha256 AND NEW.queue_namespace=s.queue_namespace AND NEW.verified_at>=s.created_at
     AND public.qualification_native_report_eligible_v55(s.outcome_id,s.reservation_id,s.report_sha256,s.policy_sha256) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'submission_projection_transport_unverified';
END;

DECLARE c RECORD; prior RECORD; old_state JSONB; current_state JSONB;
BEGIN
  SELECT * INTO c FROM demo_account_controls WHERE environment=NEW.environment AND account_id=NEW.account_id FOR UPDATE;
  SELECT * INTO prior FROM demo_control_journal WHERE environment=NEW.environment AND account_id=NEW.account_id ORDER BY control_revision DESC LIMIT 1;
  current_state := c.state_json::jsonb;
  old_state := prior.event_json::jsonb->'state';
  IF c.control_revision IS DISTINCT FROM NEW.control_revision
     OR c.state_sha256 IS DISTINCT FROM NEW.state_sha256
     OR c.updated_at IS DISTINCT FROM NEW.occurred_at
     OR NEW.control_revision <> COALESCE(prior.control_revision,0)+1
     OR NEW.previous_sha256 IS DISTINCT FROM prior.event_sha256
     OR encode(sha256(convert_to(NEW.event_json,'UTF8')),'hex') IS DISTINCT FROM NEW.event_sha256
     OR NEW.event_json::jsonb IS DISTINCT FROM (CASE WHEN NEW.action='clear_stop' THEN
        jsonb_build_object('version','ctcc.demo_control_event.v2','command_id',NEW.command_id,
          'action',NEW.action,'previous_sha256',NEW.previous_sha256,'state',current_state,
          'clear_ack_sha256',(SELECT ack.ack_sha256 FROM public.demo_control_clear_acknowledgements_v2 ack
            WHERE ack.environment=NEW.environment AND ack.account_id=NEW.account_id
             AND ack.clear_control_revision=NEW.control_revision AND ack.command_id=NEW.command_id))
      ELSE jsonb_build_object(
        'version','ctcc.demo_control_event.v1','command_id',NEW.command_id,
        'action',NEW.action,'previous_sha256',NEW.previous_sha256,'state',current_state) END) THEN
    RAISE EXCEPTION 'demo_control_journal_binding_denied';
  END IF;
  IF NEW.action='clear_stop' AND NOT EXISTS (
    SELECT 1 FROM public.demo_control_clear_acknowledgements_v2 ack
    WHERE ack.environment=NEW.environment AND ack.account_id=NEW.account_id
      AND ack.command_id=NEW.command_id AND ack.clear_control_revision=NEW.control_revision
      AND ack.stopped_control_revision=prior.control_revision
      AND ack.stopped_event_sha256=prior.event_sha256
      AND ack.stopped_state_sha256=prior.state_sha256
      AND ack.clear_state_sha256=c.state_sha256 AND ack.state_json=c.state_json
      AND ack.clear_event_sha256=NEW.event_sha256 AND ack.event_json=NEW.event_json
      AND (old_state->>'emergency_stop')::boolean AND NOT c.emergency_stop
      AND c.arm_request_id IS NULL AND c.arm_expires_at IS NULL
      AND c.lease_until=(old_state->>'lease_until')::timestamptz
      AND ack.ack_json::jsonb->>'db_transaction_id'=pg_current_xact_id()::text
      AND ack.ack_json::jsonb->'db_backend_pid'=to_jsonb(pg_backend_pid())
      AND clock_timestamp()<ack.original_expires_at) THEN
    RAISE EXCEPTION 'demo_control_clear_ack_required';
  END IF;
  IF NEW.action='acquire' THEN
    IF c.arm_request_id IS NOT NULL OR (prior.control_revision IS NULL AND c.owner_epoch<>1) OR (prior.control_revision IS NOT NULL AND
       (c.owner_sha256 IS NOT DISTINCT FROM old_state->>'owner_sha256' OR c.owner_epoch <> (old_state->>'owner_epoch')::bigint+1)) THEN
      RAISE EXCEPTION 'demo_control_acquire_denied';
    END IF;
  ELSIF prior.control_revision IS NULL THEN
    IF NEW.action<>'estop' OR c.owner_epoch<>0 OR NOT c.emergency_stop THEN
      RAISE EXCEPTION 'demo_control_stopped_genesis_required';
    END IF;
  ELSIF c.owner_sha256 IS DISTINCT FROM old_state->>'owner_sha256'
     OR c.owner_epoch IS DISTINCT FROM (old_state->>'owner_epoch')::bigint THEN
    RAISE EXCEPTION 'demo_control_owner_binding_denied';
  END IF;
  IF NEW.action IN ('arm_requested','rebind','release','renew') AND NEW.occurred_at >= (old_state->>'lease_until')::timestamptz THEN
    RAISE EXCEPTION 'demo_control_expired_owner_denied';
  END IF;
  IF NEW.action IN ('arm_requested','rebind') AND c.lease_until IS DISTINCT FROM (old_state->>'lease_until')::timestamptz THEN
    RAISE EXCEPTION 'demo_control_lease_change_denied';
  END IF;
  IF NEW.action='renew' AND c.lease_until IS DISTINCT FROM NEW.occurred_at + INTERVAL '30 seconds' THEN
    RAISE EXCEPTION 'demo_control_renew_lease_denied';
  END IF;
  IF NEW.action IN ('disarm','estop') AND c.lease_until IS DISTINCT FROM GREATEST(NEW.occurred_at,(old_state->>'lease_until')::timestamptz) THEN
    RAISE EXCEPTION 'demo_control_tightening_lease_denied';
  END IF;
  IF NEW.action='arm_requested' THEN
    IF c.arm_request_id IS DISTINCT FROM NEW.command_id OR c.arm_expires_at <= NEW.occurred_at
       OR c.arm_expires_at > NEW.occurred_at + INTERVAL '30 seconds'
       OR (old_state->>'arm_expires_at')::timestamptz > NEW.occurred_at THEN
      RAISE EXCEPTION 'demo_control_arm_denied';
    END IF;
  ELSIF NEW.action IN ('acquire','disarm','estop','rebind','release') AND c.arm_request_id IS NOT NULL THEN
    RAISE EXCEPTION 'demo_control_disarm_required';
  ELSIF NEW.action='renew' AND c.arm_request_id IS NOT NULL AND
      (c.arm_request_id IS DISTINCT FROM old_state->>'arm_request_id'
       OR c.arm_expires_at IS DISTINCT FROM (old_state->>'arm_expires_at')::timestamptz) THEN
    RAISE EXCEPTION 'demo_control_renew_cannot_arm';
  END IF;
  IF NEW.action='estop' AND NOT c.emergency_stop THEN
    RAISE EXCEPTION 'demo_control_stop_required';
  END IF;
  IF NEW.action='release' AND c.lease_until IS DISTINCT FROM NEW.occurred_at THEN
    RAISE EXCEPTION 'demo_control_release_required';
  END IF;
  IF NEW.action NOT IN ('acquire','rebind') AND
     ROW(current_state->>'config_sha256',current_state->>'policy_sha256',current_state->>'credential_session_sha256') IS DISTINCT FROM
     ROW(old_state->>'config_sha256',old_state->>'policy_sha256',old_state->>'credential_session_sha256') THEN
    RAISE EXCEPTION 'demo_control_rebind_required';
  END IF;
  RETURN NEW;
END;

DECLARE event RECORD;
BEGIN
  SELECT * INTO event FROM demo_control_journal WHERE environment=NEW.environment
    AND account_id=NEW.account_id AND control_revision=NEW.control_revision;
  IF event.control_revision IS NULL OR event.state_sha256 IS DISTINCT FROM NEW.state_sha256 THEN
    RAISE EXCEPTION 'demo_control_commit_without_journal';
  END IF;
  RETURN NEW;
END;

DECLARE j JSONB; prior RECORD; lock_key BIGINT;
BEGIN
  lock_key := ('x'||substr(encode(sha256(convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||convert_to(NEW.environment,'UTF8')||decode('00','hex')||convert_to(NEW.account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint;
  PERFORM pg_advisory_xact_lock(lock_key);
  j := NEW.event_json::jsonb;
  SELECT * INTO prior FROM demo_account_capture_events WHERE capture_id=NEW.capture_id ORDER BY sequence DESC LIMIT 1;
  IF j->>'version' IS DISTINCT FROM 'ctcc.demo_account_ingestion_event.v1'
    OR j->>'capture_id' IS DISTINCT FROM NEW.capture_id
    OR (j->>'sequence')::bigint IS DISTINCT FROM NEW.sequence
    OR j->>'previous_sha256' IS DISTINCT FROM NEW.previous_sha256
    OR j->'account_complete' IS DISTINCT FROM 'false'::jsonb
    OR j->'execution_authority' IS DISTINCT FROM 'false'::jsonb
    OR jsonb_typeof(j->'data') IS DISTINCT FROM 'object'
    OR NOT COALESCE(j->>'kind' IN ('capture_start','request_start','headers_received','body_progress','body_complete','page_validated','raw_finalized','acquisition_closed','packet_recorded','terminal','recovery'),false)
    OR NOT COALESCE(j->>'outcome' IN ('in_progress','complete_recorded','failed','cancelled','interrupted_process_loss','interrupted_owner_unknown'),false)
    OR ((j->>'kind' IN ('terminal','recovery')) IS DISTINCT FROM (j->>'outcome'<>'in_progress'))
    OR j->>'admission' IS DISTINCT FROM 'DENY'
    OR encode(sha256(convert_to(NEW.event_json,'UTF8')),'hex') IS DISTINCT FROM NEW.event_sha256
    OR j->>'raw_sha256' IS DISTINCT FROM encode(sha256(NEW.raw_body),'hex')
    OR j->>'packet_sha256' IS DISTINCT FROM encode(sha256(NEW.packet_payload),'hex')
    OR NEW.chain_bytes IS DISTINCT FROM COALESCE(prior.chain_bytes,0)+octet_length(NEW.event_json)+COALESCE(octet_length(NEW.raw_body),0)+COALESCE(octet_length(NEW.packet_payload),0)
    OR NEW.sequence <> COALESCE(prior.sequence,0)+1
    OR NEW.previous_sha256 IS DISTINCT FROM prior.event_sha256 THEN
      RAISE EXCEPTION 'account_capture_event_binding_denied';
  END IF;
  IF prior.sequence IS NULL THEN
    IF j->>'kind' IS DISTINCT FROM 'capture_start' OR j->>'outcome' IS DISTINCT FROM 'in_progress'
       OR ROW(j->'data'->>'environment',j->'data'->>'account_id',j->'data'->>'settlement_currency') IS DISTINCT FROM ROW(NEW.environment,NEW.account_id,NEW.settlement_currency) THEN
      RAISE EXCEPTION 'account_capture_start_denied';
    END IF;
  ELSIF prior.event_json::jsonb->>'outcome' IS DISTINCT FROM 'in_progress'
    OR ROW(prior.environment,prior.account_id,prior.settlement_currency) IS DISTINCT FROM ROW(NEW.environment,NEW.account_id,NEW.settlement_currency) THEN
      RAISE EXCEPTION 'account_capture_append_denied';
  END IF;
  IF NEW.raw_body IS NOT NULL AND (j->>'kind' IS DISTINCT FROM 'raw_finalized' OR j->'data'->>'raw_retention' IS DISTINCT FROM 'durable_secret_checked') THEN
    RAISE EXCEPTION 'account_capture_raw_binding_denied';
  END IF;
  IF NEW.packet_payload IS NOT NULL AND j->>'kind' IS DISTINCT FROM 'packet_recorded' THEN
    RAISE EXCEPTION 'account_capture_packet_binding_denied';
  END IF;
  RETURN NEW;
END;

DECLARE parent JSONB; j JSONB; prefix TEXT; capture TEXT;
BEGIN
  SELECT document_json::jsonb, capture_id INTO parent,capture FROM demo_account_observation_batches
    WHERE environment=NEW.environment AND account_id=NEW.account_id
      AND settlement_currency=NEW.settlement_currency AND sequence=NEW.batch_sequence;
  IF parent IS NULL THEN RAISE EXCEPTION 'account_observation_member_parent_missing'; END IF;
  IF TG_TABLE_NAME='demo_account_observation_facts' THEN
    prefix := 'source'; j := NEW.fact_json::jsonb;
    IF jsonb_typeof(j) IS DISTINCT FROM 'object'
      OR jsonb_typeof(j->'family') IS DISTINCT FROM 'string'
      OR NOT COALESCE(jsonb_typeof(j->'product') IN ('string','null'),false)
      OR ROW(j->>'family',j->>'product',j->>'identity_sha256',j->>'row_sha256') IS DISTINCT FROM ROW(NEW.family,NEW.product,NEW.identity_sha256,NEW.row_sha256)
      OR jsonb_typeof(j->'generation_at') IS DISTINCT FROM 'string'
      OR (j->>'generation_at')::timestamptz IS DISTINCT FROM NEW.generation_at
      OR NOT COALESCE(jsonb_typeof(j->'fill_at') IN ('string','null'),false)
      OR (j->>'fill_at')::timestamptz IS DISTINCT FROM NEW.fill_at
      OR jsonb_typeof(j->'metadata_observations') IS DISTINCT FROM 'array'
      OR jsonb_array_length(j->'metadata_observations') IS DISTINCT FROM 1
      OR j->'metadata_observations'->0->>'capture_id' IS DISTINCT FROM capture
      OR j->'metadata_observations'->0->>'row_sha256' IS DISTINCT FROM NEW.metadata_sha256 THEN
      RAISE EXCEPTION 'account_observation_fact_binding_denied';
    END IF;
  ELSIF TG_TABLE_NAME='demo_account_observation_coverage' THEN
    prefix := 'coverage'; j := NEW.coverage_json::jsonb;
    IF j IS DISTINCT FROM jsonb_build_object('family',NEW.family,'product',NEW.product,
         'started_at',j->>'started_at','ended_at',j->>'ended_at')
      OR jsonb_typeof(j->'started_at') IS DISTINCT FROM 'string'
      OR jsonb_typeof(j->'ended_at') IS DISTINCT FROM 'string'
      OR (j->>'started_at')::timestamptz IS DISTINCT FROM NEW.started_at
      OR (j->>'ended_at')::timestamptz IS DISTINCT FROM NEW.ended_at THEN
      RAISE EXCEPTION 'account_observation_coverage_binding_denied';
    END IF;
  ELSIF TG_TABLE_NAME='demo_account_observation_findings' THEN
    prefix := 'finding'; j := NEW.finding_json::jsonb;
    IF jsonb_typeof(j) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'account_observation_finding_binding_denied';
    END IF;
  ELSE RAISE EXCEPTION 'account_observation_member_table_invalid';
  END IF;
  -- The immutable parent commits a complete contiguous ordinal set. Once
  -- committed, extra rows can only hit its PK or exceed this fixed bound.
  IF NEW.ordinal NOT BETWEEN 1 AND (parent->>(prefix||'_membership_count'))::bigint THEN
    RAISE EXCEPTION 'account_observation_late_or_excess_member_denied';
  END IF;
  RETURN NEW;
END;

DECLARE j JSONB; member RECORD; actual RECORD; expected BIGINT;
BEGIN
  j := NEW.document_json::jsonb;
  FOR member IN SELECT * FROM (VALUES
    ('demo_account_observation_facts','fact_json','source'),
    ('demo_account_observation_coverage','coverage_json','coverage'),
    ('demo_account_observation_findings','finding_json','finding')
  ) AS tables(table_name,json_column,prefix) LOOP
    EXECUTE format('SELECT count(*) AS n,min(ordinal) AS first,max(ordinal) AS last,encode(sha256(convert_to(''[''||COALESCE(string_agg(%I,'','' ORDER BY ordinal),'''')||'']'',''UTF8'')),''hex'') AS digest FROM %I WHERE environment=$1 AND account_id=$2 AND settlement_currency=$3 AND batch_sequence=$4',member.json_column,member.table_name)
      INTO actual USING NEW.environment,NEW.account_id,NEW.settlement_currency,NEW.sequence;
    expected := (j->>(member.prefix||'_membership_count'))::bigint;
    IF actual.n IS DISTINCT FROM expected
      OR (expected>0 AND (actual.first IS DISTINCT FROM 1::bigint OR actual.last IS DISTINCT FROM expected))
      OR actual.digest IS DISTINCT FROM j->>(member.prefix||'_membership_sha256') THEN
      RAISE EXCEPTION 'account_observation_membership_incomplete';
    END IF;
  END LOOP;
  RETURN NEW;
END;

DECLARE payload jsonb;
        coordinates jsonb;
        instrument_count bigint;
        distinct_instruments bigint;
        instruments_valid boolean;
        instruments_text text;
        instruments_sorted text;
        derived_window_key text;
        first_us bigint;
        last_us bigint;
        planned_us bigint;
        expected_rows bigint;
        plan_count bigint;
        plan_item jsonb;
        plan_ordinal bigint;
        expected_start_ns bigint;
        expected_symbol text;
BEGIN
  NEW.recorded_at := clock_timestamp();
  IF encode(pg_catalog.sha256(pg_catalog.convert_to(
    NEW.schedule_json,'UTF8')),'hex') IS DISTINCT FROM NEW.schedule_sha256
    OR NEW.recorded_at >= NEW.window_start
    OR NEW.recorded_at < NEW.planned_at THEN
    RAISE EXCEPTION 'gate3_schedule_timing_or_hash_denied';
  END IF;
  payload := NEW.schedule_json::jsonb;
  coordinates := payload->'coordinate_plan';
  IF encode(pg_catalog.sha256(pg_catalog.convert_to(
       NEW.coordinate_plan_json,'UTF8')),'hex') IS DISTINCT FROM
       NEW.coordinate_plan_sha256
    OR NEW.coordinate_plan_json::jsonb IS DISTINCT FROM coordinates
    OR pg_catalog.jsonb_typeof(coordinates->'instrument_ids')
       IS DISTINCT FROM 'array'
    OR pg_catalog.jsonb_array_length(coordinates->'instrument_ids')
       NOT BETWEEN 1 AND 4096 THEN
    RAISE EXCEPTION 'gate3_schedule_coordinates_denied';
  END IF;
  SELECT count(*),count(DISTINCT instrument COLLATE "C"),
         bool_and(kind='string' AND instrument COLLATE "C" ~
           '^[A-Z0-9]{2,20}-USDT-SWAP$'),
         string_agg(instrument,chr(31) ORDER BY ordinal),
         string_agg(instrument,chr(31) ORDER BY instrument COLLATE "C")
    INTO instrument_count,distinct_instruments,instruments_valid,
         instruments_text,instruments_sorted
    FROM (
      SELECT item #>> '{}' AS instrument,
             pg_catalog.jsonb_typeof(item) AS kind,ordinal
      FROM pg_catalog.jsonb_array_elements(coordinates->'instrument_ids')
        WITH ORDINALITY AS t(item,ordinal)
    ) instruments;
  IF instrument_count NOT BETWEEN 1 AND 4096
    OR instrument_count <> distinct_instruments
    OR instruments_valid IS DISTINCT FROM true
    OR instruments_text IS DISTINCT FROM instruments_sorted
    OR coordinates->>'source' IS DISTINCT FROM 'okx.public_market_source'
    OR coordinates->>'source_version' IS DISTINCT FROM
       'okx.history_candles.nine_strings.v1'
    OR coordinates->>'schema_version' IS DISTINCT FROM
       'ctcc.mie.gate3.coordinate_plan.v1'
    OR coalesce(coordinates->>'origin','') NOT IN
       ('https://openapi.okx.com','https://us.okx.com',
        'https://eea.okx.com') THEN
    RAISE EXCEPTION 'gate3_schedule_coordinates_denied';
  END IF;
  first_us := (EXTRACT(EPOCH FROM NEW.window_start)*1000000)::bigint;
  last_us := (EXTRACT(EPOCH FROM NEW.window_end)*1000000)::bigint;
  planned_us := (EXTRACT(EPOCH FROM NEW.planned_at)*1000000)::bigint;
  expected_rows := (last_us-first_us)/60000000*instrument_count;
  IF first_us % 60000000 <> 0 OR last_us % 60000000 <> 0
    OR last_us <= first_us
    OR (last_us-first_us) % 60000000 <> 0
    OR expected_rows NOT BETWEEN 1 AND 4096
    OR (coordinates->>'expected_rows')::bigint
       IS DISTINCT FROM expected_rows
    OR (coordinates->>'interval_seconds')::bigint
       IS DISTINCT FROM 60
    OR pg_catalog.jsonb_typeof(payload->'plans') IS DISTINCT FROM 'array'
    OR pg_catalog.jsonb_array_length(payload->'plans') <> expected_rows
    THEN
    RAISE EXCEPTION 'gate3_schedule_coverage_denied';
  END IF;
  FOR plan_item,plan_ordinal IN
    SELECT item,ordinal
    FROM pg_catalog.jsonb_array_elements(payload->'plans')
      WITH ORDINALITY AS t(item,ordinal)
  LOOP
    expected_start_ns := (
      first_us + ((plan_ordinal-1)/instrument_count)*60000000
    )*1000;
    expected_symbol := (coordinates->'instrument_ids')->>
      (((plan_ordinal-1)%instrument_count)::int);
    IF pg_catalog.jsonb_typeof(plan_item) IS DISTINCT FROM 'object'
      OR plan_item->>'schema_version' IS DISTINCT FROM
         'ctcc.public.minute_plan.v1'
      OR plan_item->>'origin' IS DISTINCT FROM coordinates->>'origin'
      OR plan_item->>'instrument_id' IS DISTINCT FROM expected_symbol
      OR plan_item->>'instrument_type' IS DISTINCT FROM 'SWAP'
      OR plan_item->>'environment' IS DISTINCT FROM 'public_production'
      OR plan_item->>'source_parser' IS DISTINCT FROM
         coordinates->>'source_version'
      OR (plan_item->>'interval_seconds')::bigint IS DISTINCT FROM 60
      OR (plan_item->>'expected_rows')::bigint IS DISTINCT FROM 1
      OR (plan_item->>'created_ns')::bigint
         IS DISTINCT FROM planned_us*1000
      OR (plan_item->>'start_ns')::bigint
         IS DISTINCT FROM expected_start_ns
      OR (plan_item->>'end_ns')::bigint
         IS DISTINCT FROM expected_start_ns+60000000000
      THEN
      RAISE EXCEPTION 'gate3_schedule_plan_coordinate_denied';
    END IF;
  END LOOP;
  derived_window_key := encode(pg_catalog.sha256(pg_catalog.convert_to(
    pg_catalog.concat_ws(chr(31),coordinates->>'source',instruments_text,
      first_us::text,last_us::text),
    'UTF8')),'hex');
  IF payload->>'schema_version' IS DISTINCT FROM
       'ctcc.mie.gate3.capture_schedule.v1'
    OR payload->>'preregistration_sha256' IS DISTINCT FROM
       NEW.seal_sha256
    OR payload->>'coordinate_plan_sha256' IS DISTINCT FROM
       NEW.coordinate_plan_sha256
    OR payload->'coordinate_plan'->>'holdout_id' IS DISTINCT FROM
       NEW.holdout_id
    OR NEW.window_key IS DISTINCT FROM derived_window_key
    OR (payload->'coordinate_plan'->>'start_at')::timestamptz
       IS DISTINCT FROM NEW.window_start
    OR (payload->'coordinate_plan'->>'end_at')::timestamptz
       IS DISTINCT FROM NEW.window_end
    OR (payload->>'planned_at')::timestamptz
       IS DISTINCT FROM NEW.planned_at THEN
    RAISE EXCEPTION 'gate3_schedule_identity_denied';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF p_schedule_sha !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'gate3_schedule_ack_identity_denied';
  END IF;
  -- Fail immediately on concurrent DDL, including a downgrade. The row
  -- lock in the trigger likewise never waits for a conflicting writer.
  LOCK TABLE public.gate3_capture_schedule_pins
    IN ROW SHARE MODE NOWAIT;
  LOCK TABLE public.gate3_capture_schedule_publication_acks
    IN ROW EXCLUSIVE MODE NOWAIT;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    ('x'||pg_catalog.substr(p_schedule_sha,1,16))::bit(64)::bigint)
  THEN RAISE EXCEPTION 'gate3_schedule_ack_busy';
  END IF;
  INSERT INTO public.gate3_capture_schedule_publication_acks (
    schedule_sha256,seal_sha256,coordinate_plan_sha256,
    window_key,holdout_id,window_start,window_end,schedule_recorded_at
  ) SELECT p.schedule_sha256,p.seal_sha256,p.coordinate_plan_sha256,
           p.window_key,p.holdout_id,p.window_start,p.window_end,
           p.recorded_at
    FROM public.gate3_capture_schedule_pins p
    WHERE p.schedule_sha256=p_schedule_sha
      AND p.seal_sha256=p_seal_sha
      AND p.coordinate_plan_sha256=p_coordinate_sha
      AND p.window_key=p_window_key
      AND p.holdout_id=p_holdout_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_schedule_ack_identity_denied';
  END IF;
END;

BEGIN
  RETURN pg_catalog.jsonb_typeof(p) = 'object'
    AND p ?& keys AND (p - keys) = '{}'::jsonb;
END;

DECLARE kind text; result text;
BEGIN
  kind := pg_catalog.jsonb_typeof(p);
  IF kind = 'object' THEN
    SELECT '{' || coalesce(pg_catalog.string_agg(
      pg_catalog.to_json(item.key)::text || ':' ||
        public.gate3_schedule_canonical_jsonb(item.value),
      ',' ORDER BY item.key COLLATE "C"), '') || '}'
    INTO result FROM pg_catalog.jsonb_each(p) AS item;
    RETURN result;
  ELSIF kind = 'array' THEN
    SELECT '[' || coalesce(pg_catalog.string_agg(
      public.gate3_schedule_canonical_jsonb(item.value),
      ',' ORDER BY item.ordinal), '') || ']'
    INTO result FROM pg_catalog.jsonb_array_elements(p)
      WITH ORDINALITY AS item(value,ordinal);
    RETURN result;
  ELSIF kind = 'string' THEN
    RETURN pg_catalog.to_json(p #>> '{}')::text;
  ELSIF kind IN ('number','boolean','null') THEN
    RETURN p::text;
  END IF;
  RAISE EXCEPTION 'gate3_schedule_json_kind_denied';
END;

DECLARE kind text; member record; ascii_value text;
BEGIN
  kind := pg_catalog.jsonb_typeof(p);
  IF kind = 'string' THEN
    ascii_value := p #>> '{}';
    RETURN pg_catalog.octet_length(ascii_value) =
      pg_catalog.length(ascii_value);
  ELSIF kind = 'object' THEN
    FOR member IN SELECT item.key,item.value
      FROM pg_catalog.jsonb_each(p) AS item(key,value) LOOP
      IF pg_catalog.octet_length(member.key) <>
           pg_catalog.length(member.key)
        OR NOT public.gate3_schedule_all_ascii(member.value)
      THEN RETURN false;
      END IF;
    END LOOP;
    RETURN true;
  ELSIF kind = 'array' THEN
    FOR member IN SELECT item.value
      FROM pg_catalog.jsonb_array_elements(p) AS item(value)
    LOOP
      IF NOT public.gate3_schedule_all_ascii(member.value) THEN
        RETURN false;
      END IF;
    END LOOP;
    RETURN true;
  END IF;
  RETURN kind IN ('number','boolean','null');
END;

DECLARE key text;
BEGIN
  FOREACH key IN ARRAY strings LOOP
    IF pg_catalog.jsonb_typeof(p->key) IS DISTINCT FROM 'string'
    THEN RETURN false; END IF;
  END LOOP;
  FOREACH key IN ARRAY numbers LOOP
    IF pg_catalog.jsonb_typeof(p->key) IS DISTINCT FROM 'number'
    THEN RETURN false; END IF;
  END LOOP;
  FOREACH key IN ARRAY booleans LOOP
    IF pg_catalog.jsonb_typeof(p->key) IS DISTINCT FROM 'boolean'
    THEN RETURN false; END IF;
  END LOOP;
  FOREACH key IN ARRAY arrays LOOP
    IF pg_catalog.jsonb_typeof(p->key) IS DISTINCT FROM 'array'
    THEN RETURN false; END IF;
  END LOOP;
  FOREACH key IN ARRAY objects LOOP
    IF pg_catalog.jsonb_typeof(p->key) IS DISTINCT FROM 'object'
    THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END;

DECLARE pinned public.gate3_capture_schedule_pins%ROWTYPE;
BEGIN
  SELECT * INTO pinned FROM public.gate3_capture_schedule_pins
    WHERE schedule_sha256=NEW.schedule_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND OR NOT public.gate3_schedule_pin_is_canonical(pinned)
    OR NEW.seal_sha256 IS DISTINCT FROM pinned.seal_sha256
    OR NEW.coordinate_plan_sha256 IS DISTINCT FROM
       pinned.coordinate_plan_sha256
    OR NEW.window_key IS DISTINCT FROM pinned.window_key
    OR NEW.holdout_id IS DISTINCT FROM pinned.holdout_id
    OR NEW.window_start IS DISTINCT FROM pinned.window_start
    OR NEW.window_end IS DISTINCT FROM pinned.window_end
    OR NEW.schedule_recorded_at IS DISTINCT FROM pinned.recorded_at
    OR EXISTS (
      SELECT 1 FROM public.gate3_capture_schedule_legacy_inventory legacy_row
      WHERE legacy_row.classification <> 'noncanonical'
        AND (legacy_row.seal_sha256=NEW.seal_sha256
          OR legacy_row.window_key=NEW.window_key
          OR legacy_row.holdout_id=NEW.holdout_id))
  THEN RAISE EXCEPTION 'gate3_schedule_claim_identity_denied';
  END IF;
  NEW.claimed_at := pg_catalog.clock_timestamp();
  IF NEW.claimed_at < pinned.recorded_at
    OR NEW.claimed_at >= pinned.window_start
  THEN RAISE EXCEPTION 'gate3_schedule_claim_late';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'gate3_schedule_record_invalid';
  END IF;
  INSERT INTO public.gate3_capture_schedule_pins (
    schedule_sha256,seal_sha256,coordinate_plan_sha256,window_key,
    holdout_id,window_start,window_end,planned_at,coordinate_plan_json,
    schedule_json
  ) VALUES (
    p_record->>'schedule_sha256',p_record->>'seal_sha256',
    p_record->>'coordinate_plan_sha256',p_record->>'window_key',
    p_record->>'holdout_id',(p_record->>'window_start')::timestamptz,
    (p_record->>'window_end')::timestamptz,
    (p_record->>'planned_at')::timestamptz,
    p_record->>'coordinate_plan_json',p_record->>'schedule_json'
  );
END;

BEGIN
  IF p_schedule_sha !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'gate3_schedule_claim_ack_identity_denied';
  END IF;
  LOCK TABLE public.gate3_capture_schedule_pins
    IN ROW SHARE MODE NOWAIT;
  LOCK TABLE public.gate3_capture_schedule_key_claims
    IN ROW SHARE MODE NOWAIT;
  LOCK TABLE public.gate3_capture_schedule_claim_acks
    IN ROW EXCLUSIVE MODE NOWAIT;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    ('x'||pg_catalog.substr(p_schedule_sha,1,16))::bit(64)::bigint)
  THEN RAISE EXCEPTION 'gate3_schedule_claim_ack_busy';
  END IF;
  INSERT INTO public.gate3_capture_schedule_claim_acks (
    schedule_sha256,seal_sha256,coordinate_plan_sha256,window_key,
    holdout_id,window_start,window_end,schedule_recorded_at,
    claim_recorded_at)
  SELECT c.schedule_sha256,c.seal_sha256,c.coordinate_plan_sha256,
         c.window_key,c.holdout_id,c.window_start,c.window_end,
         c.schedule_recorded_at,c.claimed_at
    FROM public.gate3_capture_schedule_key_claims c
    WHERE c.schedule_sha256=p_schedule_sha
      AND c.seal_sha256=p_seal_sha
      AND c.coordinate_plan_sha256=p_coordinate_sha
      AND c.window_key=p_window_key
      AND c.holdout_id=p_holdout_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_schedule_claim_ack_identity_denied';
  END IF;
END;

DECLARE kind text; member record;
BEGIN
  kind := pg_catalog.jsonb_typeof(p);
  IF kind = 'number' THEN
    RETURN p::text ~ '^-?(0|[1-9][0-9]*)$';
  ELSIF kind = 'object' THEN
    FOR member IN SELECT item.value
      FROM pg_catalog.jsonb_each(p) AS item(key,value) LOOP
      IF NOT public.gate3_prereg_integer_numbers(member.value)
      THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  ELSIF kind = 'array' THEN
    FOR member IN SELECT item.value
      FROM pg_catalog.jsonb_array_elements(p) AS item(value)
    LOOP
      IF NOT public.gate3_prereg_integer_numbers(member.value)
      THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  END IF;
  RETURN kind IN ('string','boolean','null');
END;

DECLARE sealed public.gate3_preregistration_seals%ROWTYPE;
BEGIN
  IF NOT public.gate3_prereg_direct_role_allowed('seal_ack')
  THEN RAISE EXCEPTION 'gate3_prereg_seal_ack_role_denied'; END IF;
  SELECT * INTO sealed FROM public.gate3_preregistration_seals
    WHERE seal_sha256=NEW.seal_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND
    OR NEW.preregistration_id IS DISTINCT FROM sealed.preregistration_id
    OR NEW.coordinate_plan_sha256 IS DISTINCT FROM
       sealed.coordinate_plan_sha256
    OR NEW.window_key IS DISTINCT FROM sealed.window_key
    OR NEW.holdout_id IS DISTINCT FROM sealed.holdout_id
    OR NEW.window_start IS DISTINCT FROM sealed.window_start
    OR NEW.window_end IS DISTINCT FROM sealed.window_end
    OR NEW.seal_recorded_at IS DISTINCT FROM sealed.recorded_at
  THEN RAISE EXCEPTION 'gate3_prereg_seal_ack_identity_denied'; END IF;
  NEW.acknowledged_at := pg_catalog.clock_timestamp();
  IF NEW.acknowledged_at < sealed.recorded_at
    OR NEW.acknowledged_at >= sealed.window_start
  THEN RAISE EXCEPTION 'gate3_prereg_seal_ack_late'; END IF;
  RETURN NEW;
END;

DECLARE v_window_key text;
BEGIN
  IF p_sha !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'gate3_prereg_seal_ack_identity_denied';
  END IF;
  IF NOT public.gate3_prereg_direct_role_allowed('seal_ack') THEN
    RAISE EXCEPTION 'gate3_prereg_seal_ack_role_denied';
  END IF;
  LOCK TABLE public.gate3_preregistration_seals
    IN ROW SHARE MODE NOWAIT;
  LOCK TABLE public.gate3_preregistration_seal_acks
    IN ROW EXCLUSIVE MODE NOWAIT;
  SELECT window_key INTO v_window_key
    FROM public.gate3_preregistration_seals
    WHERE seal_sha256=p_sha FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_seal_ack_identity_denied';
  END IF;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    ('x'||pg_catalog.substr(v_window_key,1,16))::bit(64)::bigint)
  THEN RAISE EXCEPTION 'gate3_prereg_seal_ack_busy'; END IF;
  INSERT INTO public.gate3_preregistration_seal_acks (
    seal_sha256,preregistration_id,coordinate_plan_sha256,window_key,holdout_id,
    window_start,window_end,seal_recorded_at)
  SELECT seal_sha256,preregistration_id,coordinate_plan_sha256,window_key,holdout_id,
    window_start,window_end,recorded_at
  FROM public.gate3_preregistration_seals WHERE seal_sha256=p_sha;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_seal_ack_identity_denied';
  END IF;
END;

BEGIN
  IF NOT public.gate3_prereg_direct_role_allowed('capture_publish')
  THEN RAISE EXCEPTION 'gate3_prereg_capture_role_denied'; END IF;
  RETURN NEW;
END;

BEGIN
  IF NOT public.gate3_prereg_direct_role_allowed('capture_ack')
  THEN RAISE EXCEPTION 'gate3_prereg_capture_ack_role_denied'; END IF;
  RETURN NEW;
END;

DECLARE pinned public.gate3_capture_schedule_pins%ROWTYPE;
        sealed public.gate3_preregistration_seals%ROWTYPE;
        acknowledged public.gate3_preregistration_seal_acks%ROWTYPE;
BEGIN
  SELECT * INTO pinned FROM public.gate3_capture_schedule_pins
    WHERE schedule_sha256=NEW.schedule_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_claim_pin_missing';
  END IF;
  SELECT * INTO sealed FROM public.gate3_preregistration_seals
    WHERE seal_sha256=NEW.seal_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_claim_seal_missing';
  END IF;
  SELECT * INTO acknowledged FROM public.gate3_preregistration_seal_acks
    WHERE seal_sha256=NEW.seal_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_claim_ack_missing';
  END IF;
  IF NEW.seal_sha256 IS DISTINCT FROM pinned.seal_sha256
    OR acknowledged.preregistration_id IS DISTINCT FROM
       sealed.preregistration_id
    OR sealed.coordinate_plan_sha256 IS DISTINCT FROM
       pinned.coordinate_plan_sha256
    OR sealed.window_key IS DISTINCT FROM pinned.window_key
    OR sealed.holdout_id IS DISTINCT FROM pinned.holdout_id
    OR sealed.window_start IS DISTINCT FROM pinned.window_start
    OR sealed.window_end IS DISTINCT FROM pinned.window_end
    OR acknowledged.coordinate_plan_sha256 IS DISTINCT FROM
       sealed.coordinate_plan_sha256
    OR acknowledged.window_key IS DISTINCT FROM sealed.window_key
    OR acknowledged.holdout_id IS DISTINCT FROM sealed.holdout_id
    OR acknowledged.window_start IS DISTINCT FROM sealed.window_start
    OR acknowledged.window_end IS DISTINCT FROM sealed.window_end
    OR acknowledged.seal_recorded_at IS DISTINCT FROM sealed.recorded_at
    OR NOT sealed.created_at <= sealed.recorded_at
    OR NOT sealed.recorded_at <= acknowledged.acknowledged_at
    OR NOT acknowledged.acknowledged_at < pinned.planned_at
    OR NOT pinned.planned_at <= pinned.recorded_at
    OR pg_catalog.clock_timestamp() >= pinned.window_start
  THEN RAISE EXCEPTION 'gate3_prereg_claim_identity_denied'; END IF;
  RETURN NEW;
END;

DECLARE claimed public.gate3_capture_schedule_key_claims%ROWTYPE;
        pinned public.gate3_capture_schedule_pins%ROWTYPE;
        acknowledged public.gate3_preregistration_seal_acks%ROWTYPE;
BEGIN
  SELECT * INTO claimed FROM public.gate3_capture_schedule_key_claims
    WHERE schedule_sha256=NEW.schedule_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_capture_ack_unsealed';
  END IF;
  SELECT * INTO pinned FROM public.gate3_capture_schedule_pins
    WHERE schedule_sha256=NEW.schedule_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate3_prereg_capture_ack_unsealed';
  END IF;
  SELECT * INTO acknowledged FROM public.gate3_preregistration_seal_acks
    WHERE seal_sha256=claimed.seal_sha256 FOR KEY SHARE NOWAIT;
  IF NOT FOUND OR claimed.seal_sha256 IS DISTINCT FROM pinned.seal_sha256
    OR acknowledged.coordinate_plan_sha256 IS DISTINCT FROM
       pinned.coordinate_plan_sha256
    OR acknowledged.window_key IS DISTINCT FROM pinned.window_key
    OR acknowledged.holdout_id IS DISTINCT FROM pinned.holdout_id
    OR NOT acknowledged.acknowledged_at < pinned.planned_at
  THEN RAISE EXCEPTION 'gate3_prereg_capture_ack_unsealed'; END IF;
  RETURN NEW;
END;

BEGIN
  IF p_journal_key !~ '^[a-f0-9]{64}$'
    OR p_revision NOT BETWEEN 1 AND 8192
    OR p_record_sha !~ '^[a-f0-9]{64}$'
    OR p_checkpoint_sha !~ '^[a-f0-9]{64}$'
  THEN RAISE EXCEPTION 'public_receipt_ack_identity_denied';
  END IF;
  LOCK TABLE public.public_receipt_witness_revisions
    IN ROW SHARE MODE NOWAIT;
  LOCK TABLE public.public_receipt_publication_acks
    IN ROW EXCLUSIVE MODE NOWAIT;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    ('x'||pg_catalog.substr(p_journal_key,1,16))::bit(64)::bigint)
  THEN RAISE EXCEPTION 'public_receipt_ack_busy';
  END IF;
  INSERT INTO public.public_receipt_publication_acks (
    journal_key,witness_revision,witness_record_sha256,
    checkpoint_sha256)
  VALUES (p_journal_key,p_revision,p_record_sha,p_checkpoint_sha);
END;

BEGIN
    IF NEW.control_revision IS DISTINCT FROM OLD.control_revision + 1 THEN
        RAISE EXCEPTION 'demo_automation_control_revision_must_advance'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.restart_latch_required AND NOT NEW.restart_latch_required THEN
        RAISE EXCEPTION 'demo_automation_restart_latch_cannot_clear'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;

DECLARE j JSONB; c RECORD; k TEXT;
BEGIN
  SELECT * INTO c FROM public.g12_invocation_claims WHERE invocation_id=NEW.invocation_id FOR KEY SHARE;
  NEW.db_recorded_at := clock_timestamp();
  j := NEW.publication_json::jsonb;
  IF c.invocation_id IS NULL
    OR (SELECT count(*) FROM jsonb_object_keys(j)) IS DISTINCT FROM 13::bigint
    OR NEW.claim_sha256 IS DISTINCT FROM c.claim_sha256
    OR NEW.db_recorded_at < c.db_claimed_at
    OR encode(sha256(convert_to(NEW.publication_json,'UTF8')),'hex') IS DISTINCT FROM NEW.publication_sha256
    OR j->>'schema_version' IS DISTINCT FROM 'ctcc.g12.invocation_publication.v1'
    OR j->>'invocation_id' IS DISTINCT FROM NEW.invocation_id
    OR j->>'claim_sha256' IS DISTINCT FROM c.claim_sha256
    OR j->>'evidence_root_sha256' IS DISTINCT FROM c.claim_json::jsonb->>'evidence_root_sha256'
    OR j->>'candidate_sha256' IS DISTINCT FROM c.claim_json::jsonb->>'candidate_sha256'
    OR j->>'event_key' IS DISTINCT FROM c.event_key
    OR j->>'admission' IS DISTINCT FROM 'DENY'
    OR j->'publication_provenance_verified' IS DISTINCT FROM 'false'::jsonb
    OR j->'execution_authority' IS DISTINCT FROM 'false'::jsonb
    OR COALESCE(j->>'evidence_sha256','') !~ '^[a-f0-9]{64}$'
    OR COALESCE(j->>'report_sha256','') !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(j->'file_sha256') IS DISTINCT FROM 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(j->'file_sha256')) IS DISTINCT FROM 6::bigint
    OR j->>'publication_completed_at' IS NULL
    OR (j->>'publication_completed_at')::timestamptz <= c.db_claimed_at
    OR (j->>'publication_completed_at')::timestamptz > NEW.db_recorded_at
    OR (j->>'publication_completed_at')::timestamptz >= (c.claim_json::jsonb->>'deadline')::timestamptz THEN
    RAISE EXCEPTION 'g12_publication_denied';
  END IF;
  FOREACH k IN ARRAY ARRAY['4h.png','1h.png','15m.png','5m.png','summary.png','report.json'] LOOP
    IF COALESCE(j->'file_sha256'->>k,'') !~ '^[a-f0-9]{64}$' THEN
      RAISE EXCEPTION 'g12_publication_file_denied';
    END IF;
  END LOOP;
  RETURN NEW;
END;

DECLARE parent JSONB; j JSONB; prefix TEXT; capture TEXT;
BEGIN
  SELECT document_json::jsonb,capture_id INTO parent,capture
    FROM public.demo_account_observation_typed_batches
    WHERE environment=NEW.environment AND account_id=NEW.account_id
      AND settlement_currency=NEW.settlement_currency AND sequence=NEW.batch_sequence
    FOR KEY SHARE;
  IF parent IS NULL THEN RAISE EXCEPTION 'account_observation_typed_member_parent_missing'; END IF;
  IF TG_TABLE_NAME='demo_account_observation_typed_facts' THEN
    prefix := 'source'; j := NEW.fact_json::jsonb;
    IF jsonb_typeof(j) IS DISTINCT FROM 'object'
      OR j ? 'generation_at'
      OR jsonb_typeof(j->'family') IS DISTINCT FROM 'string'
      OR NOT COALESCE(jsonb_typeof(j->'product') IN ('string','null'),false)
      OR ROW(j->>'family',j->>'product',j->>'identity_sha256',j->>'row_sha256')
         IS DISTINCT FROM ROW(NEW.family,NEW.product,NEW.identity_sha256,NEW.row_sha256)
      OR j->>'source_ts_semantics' IS DISTINCT FROM NEW.source_ts_semantics
      OR jsonb_typeof(j->'source_ts_at') IS DISTINCT FROM 'string'
      OR (j->>'source_ts_at')::timestamptz IS DISTINCT FROM NEW.source_ts_at
      OR NOT COALESCE(jsonb_typeof(j->'fill_at') IN ('string','null'),false)
      OR (j->>'fill_at')::timestamptz IS DISTINCT FROM NEW.fill_at
      OR (NEW.family='bills' AND NEW.fill_at IS NOT NULL)
      OR jsonb_typeof(j->'metadata_observations') IS DISTINCT FROM 'array'
      OR jsonb_array_length(j->'metadata_observations') IS DISTINCT FROM 1
      OR j->'metadata_observations'->0->>'capture_id' IS DISTINCT FROM capture
      OR j->'metadata_observations'->0->>'row_sha256' IS DISTINCT FROM NEW.metadata_sha256 THEN
      RAISE EXCEPTION 'account_observation_typed_fact_binding_denied';
    END IF;
  ELSIF TG_TABLE_NAME='demo_account_observation_typed_coverage' THEN
    prefix := 'coverage'; j := NEW.coverage_json::jsonb;
    IF j IS DISTINCT FROM jsonb_build_object(
           'family',NEW.family,'product',NEW.product,'time_domain',NEW.time_domain,
           'started_at',j->>'started_at','ended_at',j->>'ended_at')
      OR jsonb_typeof(j->'started_at') IS DISTINCT FROM 'string'
      OR jsonb_typeof(j->'ended_at') IS DISTINCT FROM 'string'
      OR (j->>'started_at')::timestamptz IS DISTINCT FROM NEW.started_at
      OR (j->>'ended_at')::timestamptz IS DISTINCT FROM NEW.ended_at THEN
      RAISE EXCEPTION 'account_observation_typed_coverage_binding_denied';
    END IF;
  ELSIF TG_TABLE_NAME='demo_account_observation_typed_findings' THEN
    prefix := 'finding'; j := NEW.finding_json::jsonb;
    IF jsonb_typeof(j) IS DISTINCT FROM 'object'
      OR jsonb_typeof(j->'kind') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'account_observation_typed_finding_binding_denied';
    END IF;
  ELSE RAISE EXCEPTION 'account_observation_typed_member_table_invalid';
  END IF;
  IF NEW.ordinal NOT BETWEEN 1 AND (parent->>(prefix||'_membership_count'))::bigint THEN
    RAISE EXCEPTION 'account_observation_typed_late_or_excess_member_denied';
  END IF;
  RETURN NEW;
END;

DECLARE j JSONB; a JSONB; prior_anchor JSONB;
        member RECORD; actual RECORD; expected BIGINT;
BEGIN
  j := NEW.document_json::jsonb;
  a := NEW.receipt_json::jsonb->'continuation_anchor';
  IF NEW.sequence>1 THEN
    SELECT receipt_json::jsonb->'continuation_anchor' INTO prior_anchor
      FROM public.demo_account_observation_typed_batches
      WHERE environment=NEW.environment AND account_id=NEW.account_id
        AND settlement_currency=NEW.settlement_currency
        AND sequence=NEW.sequence-1;
    IF prior_anchor IS NULL THEN
      RAISE EXCEPTION 'account_observation_typed_predecessor_missing';
    END IF;
  END IF;
  FOR member IN SELECT * FROM (VALUES
    ('demo_account_observation_typed_facts','fact_json','source'),
    ('demo_account_observation_typed_coverage','coverage_json','coverage'),
    ('demo_account_observation_typed_findings','finding_json','finding')
  ) AS tables(table_name,json_column,prefix) LOOP
    EXECUTE format('SELECT count(*) AS n,min(ordinal) AS first,max(ordinal) AS last,encode(sha256(convert_to(''[''||COALESCE(string_agg(%I,'','' ORDER BY ordinal),'''')||'']'',''UTF8'')),''hex'') AS digest FROM public.%I WHERE environment=$1 AND account_id=$2 AND settlement_currency=$3 AND batch_sequence=$4',member.json_column,member.table_name)
      INTO actual USING NEW.environment,NEW.account_id,NEW.settlement_currency,NEW.sequence;
    expected := (j->>(member.prefix||'_membership_count'))::bigint;
    IF actual.n IS DISTINCT FROM expected
      OR (expected>0 AND (actual.first IS DISTINCT FROM 1::bigint OR actual.last IS DISTINCT FROM expected))
      OR actual.digest IS DISTINCT FROM j->>(member.prefix||'_membership_sha256') THEN
      RAISE EXCEPTION 'account_observation_typed_membership_incomplete';
    END IF;
  END LOOP;
  IF (a->>'source_facts_through_sequence')::bigint IS DISTINCT FROM
       COALESCE((prior_anchor->>'source_facts_through_sequence')::bigint,0)
       +(j->>'source_membership_count')::bigint
    OR (a->>'coverage_through_sequence')::bigint IS DISTINCT FROM
       COALESCE((prior_anchor->>'coverage_through_sequence')::bigint,0)
       +(j->>'coverage_membership_count')::bigint
    OR (a->>'unresolved_findings_through_sequence')::bigint IS DISTINCT FROM
       COALESCE((prior_anchor->>'unresolved_findings_through_sequence')::bigint,0)
       +(j->>'finding_membership_count')::bigint THEN
    RAISE EXCEPTION 'account_observation_typed_prefix_count_denied';
  END IF;
  RETURN NEW;
END;

BEGIN
  IF NEW.bundle_id !~ '^[a-f0-9]{32}$'
    OR NEW.bundle_sha256 !~ '^[a-f0-9]{64}$'
    OR NEW.proof_envelope_sha256 !~ '^[a-f0-9]{64}$'
    OR NEW.contract_version <> 1
    OR pg_catalog.octet_length(NEW.bundle_raw) NOT BETWEEN 1 AND 67108864
    OR pg_catalog.encode(pg_catalog.sha256(NEW.bundle_raw),'hex') <> NEW.bundle_sha256
  THEN RAISE EXCEPTION 'runtime_bundle_input_denied'; END IF;
  NEW.recorded_at := pg_catalog.clock_timestamp();
  RETURN NEW;
END;

BEGIN
  IF pg_catalog.current_setting('synchronous_commit') <> 'on'
    OR pg_catalog.current_setting('fsync') <> 'on'
    OR pg_catalog.current_setting('full_page_writes') <> 'on'
    OR pg_catalog.pg_is_in_recovery()
  THEN RAISE EXCEPTION 'runtime_bundle_durability_denied'; END IF;
  INSERT INTO public.public_runtime_raw_bundles_v1
    (bundle_id,bundle_sha256,proof_envelope_sha256,bundle_raw,contract_version)
  VALUES (p_bundle_id,p_bundle_sha256,p_proof_envelope_sha256,p_bundle_raw,1);
END;

DECLARE h public.demo_controlled_writer_coverage_scopes%ROWTYPE;
        c public.demo_account_controls%ROWTYPE; cj public.demo_control_journal%ROWTYPE;
        s jsonb; e jsonb; a jsonb; old_s jsonb; item record; raw text;
        k text; v jsonb; rebuilt text; ch text; encoded text; value_text text;
        i integer; code integer; low_code integer; kind text; frame jsonb;
        stack jsonb[]; stack_length integer; node_count integer; level integer;
        key_count integer; key_index integer;
        p_environment text; p_account_id text;
BEGIN
  p_environment:=NEW.environment; p_account_id:=NEW.account_id;
  PERFORM pg_catalog.pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
  SELECT * INTO c FROM public.demo_account_controls
    WHERE environment=NEW.environment AND account_id=NEW.account_id FOR UPDATE;
  SELECT * INTO h FROM public.demo_controlled_writer_coverage_scopes
    WHERE environment=NEW.environment AND account_id=NEW.account_id FOR UPDATE;
  IF c.account_id IS NULL THEN RAISE EXCEPTION 'controlled_writer_coverage_control_missing'; END IF;
  IF octet_length(NEW.state_json)>65536 OR octet_length(NEW.event_json)>32768
     OR octet_length(NEW.audit_json)>262144 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_wire_bound';
  END IF;
  IF NOT (NEW.state_json IS JSON OBJECT WITH UNIQUE KEYS)
    OR NOT (NEW.event_json IS JSON OBJECT WITH UNIQUE KEYS)
    OR NOT (NEW.audit_json IS JSON OBJECT WITH UNIQUE KEYS) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_duplicate_or_malformed'; END IF;
  s:=NEW.state_json::jsonb; e:=NEW.event_json::jsonb; a:=NEW.audit_json::jsonb;
  IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR jsonb_typeof(e) IS DISTINCT FROM 'object'
    OR jsonb_typeof(a) IS DISTINCT FROM 'object'
    OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(s) key) IS DISTINCT FROM ARRAY['account_complete','account_id','account_revision_published','audit_sha256','control_arm_request_id','control_emergency_stop','control_event_sha256','control_lease_until','control_owner_epoch','control_pins','control_revision','control_state_sha256','created_at','credential_session_sha256','deployed_manifest_sha256','environment','epoch_id','event_eligibility','execution_authority','flat_start_permission','generation','identity_sha256','journal_sequence','original_native_anchor','policy_sha256','process_domain_nonce','revocation_observed_control','revocation_reason','schema_version','source_bundle_sha256','source_chain_head_sha256','source_current_expires_at','source_current_monotonic_deadline_ns','source_current_receipt_sha256','source_custody_id','source_native_proof_sha256','source_native_readback_sha256','source_plan_sha256','source_proof_envelope_sha256','state','transition_stamp','updated_at','writer_inventory_sha256']::text[]
    OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(e) key) IS DISTINCT FROM ARRAY['account_id','action','audit_sha256','command_id','environment','epoch_id','generation','journal_sequence','occurred_at','previous_sha256','schema_version','state_sha256']::text[]
    OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(a) key) IS DISTINCT FROM ARRAY['account_id','blocking_reasons','currency_states','environment','execution_authority','future_writer_exclusion','legacy','requested_settlement_currency','schema_version','unresolved_intents']::text[] THEN
    RAISE EXCEPTION 'controlled_writer_coverage_shape';
  END IF;
  -- Rebuild canonical bytes using a bounded local stack, rather than assuming
  -- PostgreSQL JSONB ordering/escaping equals Python's sorted ensure_ascii JSON.
  -- The comparison also detects duplicate keys before they could be accepted:
  -- JSONB collapse cannot reproduce the original duplicate-containing bytes.
  FOREACH raw IN ARRAY ARRAY[NEW.state_json,NEW.event_json,NEW.audit_json] LOOP
    rebuilt:=''; stack:=ARRAY[jsonb_build_array('node',raw::jsonb,0)]; node_count:=0;
    WHILE cardinality(stack)>0 LOOP
      IF octet_length(rebuilt)>262144 THEN RAISE EXCEPTION 'controlled_writer_coverage_wire_bound'; END IF;
      stack_length:=cardinality(stack); frame:=stack[stack_length]; stack:=stack[1:stack_length-1];
      IF frame->>0='literal' THEN rebuilt:=rebuilt||(frame->>1); CONTINUE; END IF;
      v:=frame->1; level:=(frame->>2)::integer; kind:=jsonb_typeof(v);
      IF frame->>0<>'key' THEN node_count:=node_count+1; END IF;
      IF (frame->>0<>'key' AND level>24) OR node_count>65536 OR cardinality(stack)>262144 THEN
        RAISE EXCEPTION 'controlled_writer_coverage_wire_bound'; END IF;
      IF kind='object' THEN
        rebuilt:=rebuilt||'{'; stack:=array_append(stack,jsonb_build_array('literal','}'));
        SELECT count(*) INTO key_count FROM jsonb_each(v); key_index:=0;
        FOR item IN SELECT key,value FROM jsonb_each(v) ORDER BY key COLLATE "C" DESC LOOP
          key_index:=key_index+1;
          stack:=array_append(stack,jsonb_build_array('node',item.value,level+1));
          stack:=array_append(stack,jsonb_build_array('literal',':'));
          stack:=array_append(stack,jsonb_build_array('key',to_jsonb(item.key),level+1));
          IF key_index<key_count THEN stack:=array_append(stack,jsonb_build_array('literal',',')); END IF;
        END LOOP;
      ELSIF kind='array' THEN
        rebuilt:=rebuilt||'['; stack:=array_append(stack,jsonb_build_array('literal',']'));
        FOR item IN SELECT value,ordinality FROM jsonb_array_elements(v) WITH ORDINALITY ORDER BY ordinality DESC LOOP
          stack:=array_append(stack,jsonb_build_array('node',item.value,level+1));
          IF item.ordinality>1 THEN stack:=array_append(stack,jsonb_build_array('literal',',')); END IF;
        END LOOP;
      ELSIF kind='string' THEN
        value_text:=v#>>'{}'; encoded:='"';
        FOR i IN 1..length(value_text) LOOP
          ch:=substr(value_text,i,1); code:=ascii(ch);
          IF code=34 OR code=92 THEN encoded:=encoded||chr(92)||ch;
          ELSIF code=8 THEN encoded:=encoded||chr(92)||'b';
          ELSIF code=9 THEN encoded:=encoded||chr(92)||'t';
          ELSIF code=10 THEN encoded:=encoded||chr(92)||'n';
          ELSIF code=12 THEN encoded:=encoded||chr(92)||'f';
          ELSIF code=13 THEN encoded:=encoded||chr(92)||'r';
          ELSIF code<32 OR code>=127 THEN
            IF code<=65535 THEN encoded:=encoded||chr(92)||'u'||lpad(to_hex(code),4,'0');
            ELSE code:=code-65536; low_code:=56320+(code%1024);
              encoded:=encoded||chr(92)||'u'||lpad(to_hex(55296+(code/1024)),4,'0')||chr(92)||'u'||lpad(to_hex(low_code),4,'0'); END IF;
          ELSE encoded:=encoded||ch; END IF;
        END LOOP;
        rebuilt:=rebuilt||encoded||'"';
      ELSIF kind='number' THEN
        IF v::text !~ '^-?(0|[1-9][0-9]*)$' OR v::text='-0' THEN
          RAISE EXCEPTION 'controlled_writer_coverage_integer'; END IF;
        rebuilt:=rebuilt||v::text;
      ELSIF kind IN ('boolean','null') THEN rebuilt:=rebuilt||v::text;
      ELSE RAISE EXCEPTION 'controlled_writer_coverage_wire_type'; END IF;
    END LOOP;
    IF rebuilt IS DISTINCT FROM raw THEN RAISE EXCEPTION 'controlled_writer_coverage_noncanonical'; END IF;
  END LOOP;
  IF s->>'schema_version' IS DISTINCT FROM 'ctcc.demo_controlled_writer_coverage_state.v1'
    OR e->>'schema_version' IS DISTINCT FROM 'ctcc.demo_controlled_writer_coverage_event.v1'
    OR a->>'schema_version' IS DISTINCT FROM 'ctcc.portfolio_local_checkpoint.v2'
    OR s->>'environment' IS DISTINCT FROM NEW.environment OR s->>'account_id' IS DISTINCT FROM NEW.account_id
    OR s->>'state' IS DISTINCT FROM NEW.action OR e->>'action' IS DISTINCT FROM NEW.action
    OR e->>'environment' IS DISTINCT FROM NEW.environment OR e->>'account_id' IS DISTINCT FROM NEW.account_id
    OR s->>'epoch_id' IS DISTINCT FROM NEW.epoch_id OR e->>'epoch_id' IS DISTINCT FROM NEW.epoch_id
    OR e->>'command_id' IS DISTINCT FROM NEW.command_id
    OR e->>'previous_sha256' IS DISTINCT FROM NEW.previous_sha256
    OR e->>'state_sha256' IS DISTINCT FROM NEW.state_sha256
    OR e->>'audit_sha256' IS DISTINCT FROM NEW.audit_sha256
    OR s->>'audit_sha256' IS DISTINCT FROM NEW.audit_sha256
    OR encode(sha256(convert_to(NEW.state_json,'UTF8')),'hex') IS DISTINCT FROM NEW.state_sha256
    OR encode(sha256(convert_to(NEW.event_json,'UTF8')),'hex') IS DISTINCT FROM NEW.event_sha256
    OR encode(sha256(convert_to(NEW.audit_json,'UTF8')),'hex') IS DISTINCT FROM NEW.audit_sha256 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_binding';
  END IF;
  FOREACH k IN ARRAY ARRAY['schema_version','environment','account_id','state'] LOOP
    IF jsonb_typeof(s->k) IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'controlled_writer_coverage_wire_type'; END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['schema_version','environment','account_id','epoch_id','command_id','action','state_sha256','audit_sha256','occurred_at'] LOOP
    IF jsonb_typeof(e->k) IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'controlled_writer_coverage_wire_type'; END IF;
  END LOOP;
  IF (NEW.journal_sequence=1 AND e->'previous_sha256' IS DISTINCT FROM 'null'::jsonb)
    OR (NEW.journal_sequence>1 AND jsonb_typeof(e->'previous_sha256') IS DISTINCT FROM 'string') THEN
    RAISE EXCEPTION 'controlled_writer_coverage_wire_type'; END IF;
  FOREACH k IN ARRAY ARRAY['generation','journal_sequence','control_owner_epoch','control_revision'] LOOP
    IF jsonb_typeof(s->k) IS DISTINCT FROM 'number' OR s->>k !~ '^[1-9][0-9]{0,18}$'
      OR (s->>k)::numeric>9223372036854775807 THEN
      RAISE EXCEPTION 'controlled_writer_coverage_integer'; END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['generation','journal_sequence'] LOOP
    IF e->k IS DISTINCT FROM s->k THEN RAISE EXCEPTION 'controlled_writer_coverage_integer'; END IF;
  END LOOP;
  IF (s->>'generation')::bigint<>NEW.generation OR (s->>'journal_sequence')::bigint<>NEW.journal_sequence
    OR (s->>'updated_at')::timestamptz IS DISTINCT FROM NEW.occurred_at
    OR s->>'updated_at' IS DISTINCT FROM e->>'occurred_at'
    OR s->'control_emergency_stop' IS DISTINCT FROM 'true'::jsonb
    OR s->'control_arm_request_id' IS DISTINCT FROM 'null'::jsonb THEN
    RAISE EXCEPTION 'controlled_writer_coverage_binding'; END IF;
  FOREACH k IN ARRAY ARRAY['account_complete','account_revision_published','event_eligibility','execution_authority','flat_start_permission'] LOOP
    IF s->k IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'controlled_writer_coverage_authority_denied'; END IF;
  END LOOP;
  FOR item IN SELECT key,value FROM jsonb_each(s) WHERE key LIKE '%\_sha256' ESCAPE '\' LOOP
    IF jsonb_typeof(item.value) IS DISTINCT FROM 'string' OR item.value#>>'{}' !~ '^[a-f0-9]{64}$' THEN
      RAISE EXCEPTION 'controlled_writer_coverage_digest'; END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['epoch_id','process_domain_nonce','source_custody_id'] LOOP
    IF jsonb_typeof(s->k) IS DISTINCT FROM 'string' OR s->>k !~ '^[a-f0-9]{32}$' THEN
      RAISE EXCEPTION 'controlled_writer_coverage_identity'; END IF;
  END LOOP;
  IF jsonb_typeof(s->'control_pins') IS DISTINCT FROM 'object'
    OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(s->'control_pins') key)
      IS DISTINCT FROM ARRAY['config_sha256','credential_session_sha256','policy_sha256']::text[]
    OR EXISTS(SELECT 1 FROM jsonb_each(s->'control_pins') WHERE jsonb_typeof(value)<>'string' OR value#>>'{}' !~ '^[a-f0-9]{64}$') THEN
    RAISE EXCEPTION 'controlled_writer_coverage_pins'; END IF;
  IF s->>'policy_sha256' IS DISTINCT FROM s->'control_pins'->>'policy_sha256'
    OR s->>'credential_session_sha256' IS DISTINCT FROM s->'control_pins'->>'credential_session_sha256'
    OR a->>'environment' IS DISTINCT FROM NEW.environment OR a->>'account_id' IS DISTINCT FROM NEW.account_id
    OR jsonb_typeof(a->'account_id') IS DISTINCT FROM 'string'
    OR a->>'requested_settlement_currency' IS DISTINCT FROM 'USDT'
    OR a->'future_writer_exclusion' IS DISTINCT FROM 'false'::jsonb
    OR a->'execution_authority' IS DISTINCT FROM 'false'::jsonb
    OR a->'blocking_reasons' IS DISTINCT FROM '[]'::jsonb
    OR a->'unresolved_intents' IS DISTINCT FROM '[]'::jsonb
    OR jsonb_typeof(a->'currency_states') IS DISTINCT FROM 'array'
    OR jsonb_typeof(a->'legacy') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'controlled_writer_coverage_audit'; END IF;
  FOREACH k IN ARRAY ARRAY['original_native_anchor','transition_stamp'] LOOP
    IF jsonb_typeof(s->k) IS DISTINCT FROM 'object'
      OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(s->k) key)
        IS DISTINCT FROM ARRAY['monotonic_ns','utc_ns']::text[]
      OR EXISTS(SELECT 1 FROM jsonb_each(s->k) WHERE jsonb_typeof(value)<>'number' OR value::text !~ '^(0|[1-9][0-9]{0,19})$' OR value::text::numeric>32503680000000000000) THEN
      RAISE EXCEPTION 'controlled_writer_coverage_stamp'; END IF;
  END LOOP;
  IF jsonb_typeof(s->'source_current_monotonic_deadline_ns') IS DISTINCT FROM 'number'
    OR s->>'source_current_monotonic_deadline_ns' !~ '^(0|[1-9][0-9]{0,19})$'
    OR (s->>'source_current_monotonic_deadline_ns')::numeric>32503680000000000000 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_stamp'; END IF;
  FOREACH k IN ARRAY ARRAY['created_at','updated_at','control_lease_until','source_current_expires_at'] LOOP
    IF jsonb_typeof(s->k) IS DISTINCT FROM 'string' OR s->>k !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d{6})?\+00:00$' THEN
      RAISE EXCEPTION 'controlled_writer_coverage_time'; END IF;
  END LOOP;
  IF NEW.action<>'revoked' AND NEW.occurred_at IS DISTINCT FROM
    TIMESTAMPTZ 'epoch'+(ceil((s->'transition_stamp'->>'utc_ns')::numeric/1000)::text||' microseconds')::interval THEN
    RAISE EXCEPTION 'controlled_writer_coverage_transition_time'; END IF;
  IF NEW.action<>'revoked' THEN
    SELECT * INTO cj FROM public.demo_control_journal WHERE environment=c.environment
      AND account_id=c.account_id AND control_revision=c.control_revision;
    IF NOT c.emergency_stop OR c.arm_request_id IS NOT NULL OR c.owner_epoch<1
      OR c.lease_until<=clock_timestamp()
      OR NEW.occurred_at<c.updated_at OR NEW.occurred_at>=c.lease_until
      OR c.owner_epoch IS DISTINCT FROM (s->>'control_owner_epoch')::bigint
      OR c.control_revision IS DISTINCT FROM (s->>'control_revision')::bigint
      OR c.state_sha256 IS DISTINCT FROM s->>'control_state_sha256'
      OR cj.event_sha256 IS DISTINCT FROM s->>'control_event_sha256'
      OR encode(sha256(convert_to(cj.event_json,'UTF8')),'hex') IS DISTINCT FROM cj.event_sha256
      OR jsonb_build_object('config_sha256',c.state_json::jsonb->'config_sha256',
         'policy_sha256',c.state_json::jsonb->'policy_sha256',
         'credential_session_sha256',c.state_json::jsonb->'credential_session_sha256') IS DISTINCT FROM s->'control_pins'
      OR c.lease_until IS DISTINCT FROM (s->>'control_lease_until')::timestamptz
      OR (s->>'source_current_expires_at')::timestamptz<=clock_timestamp()
      OR s->'revocation_reason' IS DISTINCT FROM 'null'::jsonb
      OR s->'revocation_observed_control' IS DISTINCT FROM 'null'::jsonb THEN
      RAISE EXCEPTION 'controlled_writer_coverage_control_denied'; END IF;
  ELSE
    IF jsonb_typeof(s->'revocation_reason') IS DISTINCT FROM 'string'
      OR s->>'revocation_reason' NOT IN ('commit_or_readback_uncertain','control_changed','expired','explicit_disarm','local_state_changed','restart_reconciliation_required','source_changed') THEN
      RAISE EXCEPTION 'controlled_writer_coverage_revocation'; END IF;
    IF s->'revocation_observed_control' IS DISTINCT FROM
      jsonb_build_object('revision',c.control_revision,'owner_epoch',c.owner_epoch,
      'event_sha256',(SELECT event_sha256 FROM public.demo_control_journal WHERE environment=c.environment AND account_id=c.account_id AND control_revision=c.control_revision),
      'state_sha256',c.state_sha256,'emergency_stop',c.emergency_stop,'arm_request_id',c.arm_request_id) THEN
      RAISE EXCEPTION 'controlled_writer_coverage_revocation'; END IF;
  END IF;
  IF h.account_id IS NULL THEN
    IF NEW.journal_sequence<>1 OR NEW.generation<>1 OR NEW.action<>'prepared'
      OR NEW.previous_sha256 IS NOT NULL THEN RAISE EXCEPTION 'controlled_writer_coverage_initial'; END IF;
  ELSE
    old_s:=h.state_json::jsonb;
    IF NEW.journal_sequence<>h.journal_sequence+1 OR NEW.previous_sha256 IS DISTINCT FROM h.journal_sha256 THEN
      RAISE EXCEPTION 'controlled_writer_coverage_cas'; END IF;
    IF NEW.action='prepared' THEN
      IF h.state<>'revoked' OR NEW.generation<>h.generation+1 OR NEW.epoch_id=h.epoch_id
        OR (s->>'control_owner_epoch')::bigint<=(old_s->>'control_owner_epoch')::bigint
        OR s->>'source_custody_id'=old_s->>'source_custody_id'
        OR s->>'source_bundle_sha256'=old_s->>'source_bundle_sha256'
        OR s->>'process_domain_nonce'=old_s->>'process_domain_nonce'
        OR s->>'created_at' IS DISTINCT FROM old_s->>'created_at' THEN
        RAISE EXCEPTION 'controlled_writer_coverage_generation'; END IF;
    ELSE
      IF NEW.generation<>h.generation OR NEW.epoch_id<>h.epoch_id
        OR NOT ((h.state='prepared' AND NEW.action IN ('active','revoked')) OR (h.state='active' AND NEW.action='revoked'))
        OR (s-ARRAY['journal_sequence','revocation_observed_control','revocation_reason','state','transition_stamp','updated_at']::text[]) IS DISTINCT FROM (old_s-ARRAY['journal_sequence','revocation_observed_control','revocation_reason','state','transition_stamp','updated_at']::text[])
        OR NEW.audit_sha256 IS DISTINCT FROM old_s->>'audit_sha256' THEN
        RAISE EXCEPTION 'controlled_writer_coverage_transition'; END IF;
      IF NEW.action='revoked' AND s->'transition_stamp' IS DISTINCT FROM old_s->'transition_stamp' THEN
        RAISE EXCEPTION 'controlled_writer_coverage_revocation_clock_domain'; END IF;
    END IF;
    IF NEW.occurred_at<h.updated_at OR (NEW.generation=h.generation AND
      ((s->'transition_stamp'->>'utc_ns')::numeric<(old_s->'transition_stamp'->>'utc_ns')::numeric
       OR (s->'transition_stamp'->>'monotonic_ns')::numeric<(old_s->'transition_stamp'->>'monotonic_ns')::numeric)) THEN
      RAISE EXCEPTION 'controlled_writer_coverage_clock_regressed'; END IF;
  END IF;
  RETURN NEW;
END

DECLARE j public.demo_controlled_writer_coverage_journal%ROWTYPE;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.environment IS DISTINCT FROM OLD.environment
    OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.journal_sequence<>OLD.journal_sequence+1) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_scope_cas'; END IF;
  IF TG_OP='INSERT' AND (NEW.journal_sequence<>1 OR NEW.generation<>1 OR NEW.state<>'prepared') THEN
    RAISE EXCEPTION 'controlled_writer_coverage_initial'; END IF;
  SELECT * INTO j FROM public.demo_controlled_writer_coverage_journal WHERE environment=NEW.environment
    AND account_id=NEW.account_id AND journal_sequence=NEW.journal_sequence;
  IF j.account_id IS NULL OR (j.generation,j.epoch_id,j.action,j.state_json,j.state_sha256,j.event_sha256,j.occurred_at)
    IS DISTINCT FROM (NEW.generation,NEW.epoch_id,NEW.state,NEW.state_json,NEW.state_sha256,NEW.journal_sha256,NEW.updated_at)
    OR NEW.created_at IS DISTINCT FROM (NEW.state_json::jsonb->>'created_at')::timestamptz THEN
    RAISE EXCEPTION 'controlled_writer_coverage_pair'; END IF;
  RETURN NEW;
END

DECLARE h public.demo_controlled_writer_coverage_scopes%ROWTYPE;
        j public.demo_controlled_writer_coverage_journal%ROWTYPE;
BEGIN
  SELECT * INTO h FROM public.demo_controlled_writer_coverage_scopes
    WHERE environment=NEW.environment AND account_id=NEW.account_id;
  SELECT * INTO j FROM public.demo_controlled_writer_coverage_journal
    WHERE environment=NEW.environment AND account_id=NEW.account_id ORDER BY journal_sequence DESC LIMIT 1;
  IF h.account_id IS NULL OR j.account_id IS NULL
    OR (h.journal_sequence,h.generation,h.epoch_id,h.state,h.state_json,h.state_sha256,h.journal_sha256,h.updated_at)
      IS DISTINCT FROM (j.journal_sequence,j.generation,j.epoch_id,j.action,j.state_json,j.state_sha256,j.event_sha256,j.occurred_at) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_pair'; END IF;
  RETURN NULL;
END

BEGIN
  RAISE EXCEPTION 'controlled_writer_coverage_immutable';
END

DECLARE h public.demo_controlled_writer_coverage_scopes%ROWTYPE; s jsonb; e jsonb;
        seq bigint; event_hash text; state_hash text; audit_hash text;
BEGIN
  IF current_setting('role')<>'none' OR current_setting('transaction_isolation')<>'read committed'
    OR current_setting('synchronous_commit')<>'on' OR current_setting('fsync')<>'on'
    OR current_setting('full_page_writes')<>'on' OR current_setting('session_replication_role')<>'origin'
    OR pg_is_in_recovery() OR EXISTS(SELECT 1 FROM pg_roles r WHERE rolname=session_user
      AND (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls))
    OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname<>session_user AND pg_has_role(session_user,r.oid,'MEMBER'))
    OR EXISTS(SELECT 1 FROM pg_class c WHERE c.oid IN
      ('public.demo_controlled_writer_coverage_scopes'::regclass,'public.demo_controlled_writer_coverage_journal'::regclass)
      AND (c.relowner=(SELECT oid FROM pg_roles WHERE rolname=session_user)
        OR has_table_privilege(session_user,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
        OR has_any_column_privilege(session_user,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')))
    OR has_schema_privilege(session_user,'public','CREATE')
    OR has_database_privilege(session_user,current_database(),'CREATE') THEN
    RAISE EXCEPTION 'controlled_writer_coverage_role_denied'; END IF;
  IF p_environment IS DISTINCT FROM 'demo' OR p_account_id IS NULL OR p_account_id !~ '^[0-9]{1,32}$'
    OR p_expected_sequence IS NULL OR p_expected_sequence<0
    OR (p_expected_sequence=0 AND p_expected_sha256 IS NOT NULL)
    OR (p_expected_sequence>0 AND (p_expected_sha256 IS NULL OR p_expected_sha256 !~ '^[a-f0-9]{64}$'))
    OR p_state_raw IS NULL OR octet_length(p_state_raw) NOT BETWEEN 1 AND 65536
    OR p_event_raw IS NULL OR octet_length(p_event_raw) NOT BETWEEN 1 AND 32768
    OR p_audit_raw IS NULL OR octet_length(p_audit_raw) NOT BETWEEN 1 AND 262144 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_input'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
  PERFORM 1 FROM public.demo_account_controls WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
  SELECT * INTO h FROM public.demo_controlled_writer_coverage_scopes WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
  LOCK TABLE public.demo_controlled_writer_coverage_scopes, public.demo_controlled_writer_coverage_journal IN ROW EXCLUSIVE MODE NOWAIT;
  IF coalesce(h.journal_sequence,0)<>p_expected_sequence OR h.journal_sha256 IS DISTINCT FROM p_expected_sha256 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_cas'; END IF;
  IF NOT (convert_from(p_state_raw,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS)
    OR NOT (convert_from(p_event_raw,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS)
    OR NOT (convert_from(p_audit_raw,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_duplicate_or_malformed'; END IF;
  s:=convert_from(p_state_raw,'UTF8')::jsonb; e:=convert_from(p_event_raw,'UTF8')::jsonb;
  seq:=p_expected_sequence+1; state_hash:=encode(sha256(p_state_raw),'hex');
  event_hash:=encode(sha256(p_event_raw),'hex'); audit_hash:=encode(sha256(p_audit_raw),'hex');
  INSERT INTO public.demo_controlled_writer_coverage_journal
    (environment,account_id,journal_sequence,generation,epoch_id,command_id,action,previous_sha256,
     state_json,state_sha256,event_json,event_sha256,audit_json,audit_sha256,occurred_at)
    VALUES(p_environment,p_account_id,seq,(s->>'generation')::bigint,s->>'epoch_id',e->>'command_id',s->>'state',
      p_expected_sha256,convert_from(p_state_raw,'UTF8'),state_hash,convert_from(p_event_raw,'UTF8'),event_hash,
      convert_from(p_audit_raw,'UTF8'),audit_hash,(s->>'updated_at')::timestamptz);
  IF h.account_id IS NULL THEN
    INSERT INTO public.demo_controlled_writer_coverage_scopes VALUES
      (p_environment,p_account_id,(s->>'generation')::bigint,s->>'epoch_id',seq,s->>'state',convert_from(p_state_raw,'UTF8'),
       state_hash,event_hash,(s->>'created_at')::timestamptz,(s->>'updated_at')::timestamptz);
  ELSE
    UPDATE public.demo_controlled_writer_coverage_scopes SET generation=(s->>'generation')::bigint,
      epoch_id=s->>'epoch_id',journal_sequence=seq,state=s->>'state',state_json=convert_from(p_state_raw,'UTF8'),
      state_sha256=state_hash,journal_sha256=event_hash,updated_at=(s->>'updated_at')::timestamptz
      WHERE environment=p_environment AND account_id=p_account_id
      AND demo_controlled_writer_coverage_scopes.journal_sequence=p_expected_sequence
      AND journal_sha256=p_expected_sha256;
    IF NOT FOUND THEN RAISE EXCEPTION 'controlled_writer_coverage_cas'; END IF;
  END IF;
  RETURN QUERY SELECT seq,event_hash;
END

DECLARE h public.demo_controlled_writer_coverage_scopes%ROWTYPE; result jsonb;
BEGIN
  IF p_environment IS DISTINCT FROM 'demo' OR p_account_id IS NULL OR p_account_id !~ '^[0-9]{1,32}$'
    OR p_lock_mode IS NULL OR p_lock_mode NOT IN ('discover','append','readback') THEN
    RAISE EXCEPTION 'controlled_writer_coverage_selector_denied'; END IF;
  IF p_lock_mode='discover' THEN
    IF p_expected_sequence IS NOT NULL OR p_expected_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'controlled_writer_coverage_selector_denied'; END IF;
  ELSIF NOT ((p_lock_mode='append' AND p_expected_sequence=0 AND p_expected_sha256 IS NULL)
    OR (p_expected_sequence IS NOT NULL AND p_expected_sequence>0 AND p_expected_sha256 IS NOT NULL
      AND p_expected_sha256 ~ '^[a-f0-9]{64}$')) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_selector_denied';
  ELSIF p_expected_sequence IS NULL THEN
    RAISE EXCEPTION 'controlled_writer_coverage_selector_denied';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
  PERFORM 1 FROM public.demo_account_controls WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'controlled_writer_coverage_control_missing'; END IF;
  SELECT * INTO h FROM public.demo_controlled_writer_coverage_scopes
    WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
  IF p_lock_mode='append' THEN
    LOCK TABLE public.demo_controlled_writer_coverage_scopes, public.demo_controlled_writer_coverage_journal IN ROW EXCLUSIVE MODE NOWAIT;
  ELSIF p_lock_mode='readback' THEN
    LOCK TABLE public.demo_controlled_writer_coverage_scopes, public.demo_controlled_writer_coverage_journal IN SHARE MODE NOWAIT;
  END IF;
  IF p_lock_mode<>'discover' AND (coalesce(h.journal_sequence,0) IS DISTINCT FROM p_expected_sequence
    OR h.journal_sha256 IS DISTINCT FROM p_expected_sha256) THEN
    RAISE EXCEPTION 'controlled_writer_coverage_cas'; END IF;
  IF h.account_id IS NULL THEN
    IF p_lock_mode='readback' THEN RAISE EXCEPTION 'controlled_writer_coverage_cas'; END IF;
    RETURN jsonb_build_object('head',NULL,'records','[]'::jsonb,'previous_terminal_anchor',NULL);
  END IF;
  WITH r AS (
    SELECT j.* FROM public.demo_controlled_writer_coverage_journal j
    WHERE j.environment=p_environment AND j.account_id=p_account_id AND j.generation=h.generation
    ORDER BY j.journal_sequence
  ), a AS (
    SELECT j.* FROM public.demo_controlled_writer_coverage_journal j
    WHERE j.environment=p_environment AND j.account_id=p_account_id
      AND j.journal_sequence=(SELECT min(journal_sequence)-1 FROM r)
  ) SELECT jsonb_build_object('head',to_jsonb(h),'records',(SELECT jsonb_agg(to_jsonb(r) ORDER BY journal_sequence) FROM r),
      'previous_terminal_anchor',(SELECT to_jsonb(a) FROM a)) INTO result
    WHERE (SELECT count(*) FROM r) BETWEEN 1 AND 3
      AND (SELECT min(action) FROM r WHERE journal_sequence=(SELECT min(journal_sequence) FROM r))='prepared'
      AND (SELECT max(journal_sequence) FROM r)=h.journal_sequence
      AND (h.generation=1 OR EXISTS(SELECT 1 FROM a WHERE action='revoked' AND generation=h.generation-1))
      AND (h.generation<>1 OR NOT EXISTS(SELECT 1 FROM a));
  IF result IS NULL OR octet_length(result::text)>2097152 THEN
    RAISE EXCEPTION 'controlled_writer_coverage_readback'; END IF;
  RETURN result;
END

DECLARE rebuilt text; ch text; encoded text; value_text text; item record;
 i integer; code integer; low_code integer; kind text; frame jsonb;
 stack jsonb[]; stack_length integer; node_count integer; level integer;
 key_count integer; key_index integer; v jsonb;
BEGIN
    rebuilt:=''; stack:=ARRAY[jsonb_build_array('node',p_value,0)]; node_count:=0;
    WHILE cardinality(stack)>0 LOOP
      IF octet_length(rebuilt)>8388608 THEN RAISE EXCEPTION 'account_history_partition_wire_bound'; END IF;
      stack_length:=cardinality(stack); frame:=stack[stack_length]; stack:=stack[1:stack_length-1];
      IF frame->>0='literal' THEN rebuilt:=rebuilt||(frame->>1); CONTINUE; END IF;
      v:=frame->1; level:=(frame->>2)::integer; kind:=jsonb_typeof(v);
      IF frame->>0<>'key' THEN node_count:=node_count+1; END IF;
      IF (frame->>0<>'key' AND level>32) OR node_count>262144 OR cardinality(stack)>8388608 THEN
        RAISE EXCEPTION 'account_history_partition_wire_bound'; END IF;
      IF kind='object' THEN
        rebuilt:=rebuilt||'{'; stack:=array_append(stack,jsonb_build_array('literal','}'));
        SELECT count(*) INTO key_count FROM jsonb_each(v); key_index:=0;
        FOR item IN SELECT key,value FROM jsonb_each(v) ORDER BY key COLLATE "C" DESC LOOP
          key_index:=key_index+1;
          stack:=array_append(stack,jsonb_build_array('node',item.value,level+1));
          stack:=array_append(stack,jsonb_build_array('literal',':'));
          stack:=array_append(stack,jsonb_build_array('key',to_jsonb(item.key),level+1));
          IF key_index<key_count THEN stack:=array_append(stack,jsonb_build_array('literal',',')); END IF;
        END LOOP;
      ELSIF kind='array' THEN
        rebuilt:=rebuilt||'['; stack:=array_append(stack,jsonb_build_array('literal',']'));
        FOR item IN SELECT value,ordinality FROM jsonb_array_elements(v) WITH ORDINALITY ORDER BY ordinality DESC LOOP
          stack:=array_append(stack,jsonb_build_array('node',item.value,level+1));
          IF item.ordinality>1 THEN stack:=array_append(stack,jsonb_build_array('literal',',')); END IF;
        END LOOP;
      ELSIF kind='string' THEN
        value_text:=v#>>'{}'; encoded:='"';
        FOR i IN 1..length(value_text) LOOP
          ch:=substr(value_text,i,1); code:=ascii(ch);
          IF code=34 OR code=92 THEN encoded:=encoded||chr(92)||ch;
          ELSIF code=8 THEN encoded:=encoded||chr(92)||'b';
          ELSIF code=9 THEN encoded:=encoded||chr(92)||'t';
          ELSIF code=10 THEN encoded:=encoded||chr(92)||'n';
          ELSIF code=12 THEN encoded:=encoded||chr(92)||'f';
          ELSIF code=13 THEN encoded:=encoded||chr(92)||'r';
          ELSIF code<32 OR code>=127 THEN
            IF code<=65535 THEN encoded:=encoded||chr(92)||'u'||lpad(to_hex(code),4,'0');
            ELSE code:=code-65536; low_code:=56320+(code%1024);
              encoded:=encoded||chr(92)||'u'||lpad(to_hex(55296+(code/1024)),4,'0')||chr(92)||'u'||lpad(to_hex(low_code),4,'0'); END IF;
          ELSE encoded:=encoded||ch; END IF;
        END LOOP;
        rebuilt:=rebuilt||encoded||'"';
      ELSIF kind='number' THEN
        IF v::text !~ '^-?(0|[1-9][0-9]*)$' OR v::text='-0' THEN
          RAISE EXCEPTION 'account_history_partition_integer'; END IF;
        rebuilt:=rebuilt||v::text;
      ELSIF kind IN ('boolean','null') THEN rebuilt:=rebuilt||v::text;
      ELSE RAISE EXCEPTION 'account_history_partition_wire_type'; END IF;
    END LOOP;
  RETURN rebuilt;
END

BEGIN
 IF p_raw IS NULL OR octet_length(p_raw) NOT BETWEEN 1 AND 8388608 OR NOT (p_raw IS JSON OBJECT WITH UNIQUE KEYS) THEN
   RAISE EXCEPTION 'account_history_partition_json'; END IF;
 IF public.account_history_partition_v1_encode(p_raw::jsonb) IS DISTINCT FROM p_raw THEN
   RAISE EXCEPTION 'account_history_partition_noncanonical'; END IF;
 RETURN p_raw::jsonb;
END

DECLARE c public.demo_account_controls%ROWTYPE; q public.qualification_account_scopes%ROWTYPE;
BEGIN
 IF p_environment IS DISTINCT FROM 'demo' OR p_account_id !~ '^[0-9]{1,32}$'
   OR p_currency IS DISTINCT FROM 'USDT' THEN RAISE EXCEPTION 'account_history_partition_scope'; END IF;
 IF current_user=session_user OR current_setting('role')<>'none'
   OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname=session_user
     AND (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls))
   OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname<>session_user AND pg_has_role(session_user,r.oid,'MEMBER'))
   OR has_schema_privilege(session_user,'public','CREATE')
   OR has_database_privilege(session_user,current_database(),'CREATE') THEN
   RAISE EXCEPTION 'account_history_partition_role_denied'; END IF;
 IF current_setting('transaction_isolation')<>'read committed'
   OR current_setting('TimeZone')<>'UTC' OR current_setting('synchronous_commit')<>'on'
   OR current_setting('session_replication_role')<>'origin' OR pg_is_in_recovery()
   OR current_setting('fsync')<>'on' OR current_setting('full_page_writes')<>'on' THEN
   RAISE EXCEPTION 'account_history_partition_session_denied'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
 SELECT * INTO c FROM public.demo_account_controls WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
 SELECT * INTO q FROM public.qualification_account_scopes WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency FOR UPDATE;
 IF c.account_id IS NULL OR q.account_id IS NULL THEN RAISE EXCEPTION 'account_history_partition_parent_missing'; END IF;
 IF p_control_revision IS NOT NULL AND (c.control_revision<>p_control_revision OR q.account_revision<>p_account_revision OR q.ledger_revision<>p_ledger_revision
   OR NOT c.emergency_stop OR c.arm_request_id IS NOT NULL OR p_expires IS NULL
   OR p_expires<=clock_timestamp() OR p_expires>c.lease_until) THEN
   RAISE EXCEPTION 'account_history_partition_fence_changed'; END IF;
 IF (p_control_revision IS NULL)<>(p_account_revision IS NULL) OR (p_control_revision IS NULL)<>(p_ledger_revision IS NULL) THEN RAISE EXCEPTION 'account_history_partition_fence_invalid'; END IF;
 PERFORM 1 FROM public.demo_account_observation_batches WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency ORDER BY sequence DESC LIMIT 1 FOR UPDATE;
 LOCK TABLE public.qualification_account_scopes, public.demo_account_controls, public.demo_account_observation_batches, public.demo_account_capture_events,
   public.demo_account_history_native_members, public.demo_account_history_partition_checkpoints IN ROW EXCLUSIVE MODE NOWAIT;
END

DECLARE b public.demo_account_observation_batches%ROWTYPE; e public.demo_account_capture_events%ROWTYPE;
 s jsonb; l jsonb; d jsonb; a jsonb; k text; item record; previous_stamp jsonb; stamp jsonb;
 expected jsonb; root_a jsonb; root_b jsonb; total numeric; sealed bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'account_history_partition_immutable'; END IF;
 SELECT * INTO b FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency AND sequence=NEW.b3_sequence;
 SELECT * INTO e FROM public.demo_account_capture_events WHERE capture_id=NEW.capture_id AND sequence=NEW.source_sequence;
 IF b.sequence IS NULL OR e.sequence IS NULL OR b.capture_id<>NEW.capture_id OR b.source_sequence<>NEW.source_sequence
   OR b.event_sha256<>NEW.b3_event_sha256 OR b.document_json<>NEW.b3_document_json
   OR e.environment<>NEW.environment OR e.account_id<>NEW.account_id OR e.settlement_currency<>NEW.settlement_currency
   OR e.event_sha256 IS DISTINCT FROM b.document_json::jsonb->'reference'->>'head_sha256'
   OR EXISTS(SELECT 1 FROM public.demo_account_capture_events x WHERE x.capture_id=NEW.capture_id AND x.sequence>NEW.source_sequence)
   OR (SELECT max(sequence) FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency)<>NEW.b3_sequence THEN
   RAISE EXCEPTION 'account_history_partition_original_source_changed'; END IF;
 SELECT max(last_sequence) INTO sealed FROM public.demo_account_history_partition_checkpoints WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency;
 IF NEW.b3_sequence<=coalesce(sealed,0) THEN RAISE EXCEPTION 'account_history_partition_no_backfill'; END IF;
 d:=public.account_history_partition_v1_json(NEW.b3_document_json);
 s:=public.account_history_partition_v1_json(NEW.registration_json);
 IF jsonb_typeof(s->'native_linkage_json') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'account_history_partition_linkage'; END IF;
 l:=public.account_history_partition_v1_json(s->>'native_linkage_json');
 a:=public.account_history_partition_v1_json(d->>'anchor_json');
 IF encode(sha256(convert_to(NEW.b3_document_json,'UTF8')),'hex')<>NEW.b3_event_sha256
   OR encode(sha256(convert_to(NEW.registration_json,'UTF8')),'hex')<>NEW.registration_sha256
   OR d->>'anchor_sha256' IS DISTINCT FROM encode(sha256(convert_to(d->>'anchor_json','UTF8')),'hex')
   OR d->'sequence' IS DISTINCT FROM to_jsonb(NEW.b3_sequence)
   OR d->'scope_sha256' IS DISTINCT FROM to_jsonb(encode(sha256(convert_to('["demo","'||NEW.account_id||'","USDT"]','UTF8')),'hex'))
   OR d->'account_complete' IS DISTINCT FROM 'false'::jsonb OR d->'execution_authority' IS DISTINCT FROM 'false'::jsonb
   OR d->>'admission' IS DISTINCT FROM 'DENY' THEN RAISE EXCEPTION 'account_history_partition_source_binding'; END IF;
 IF (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(l) key) IS DISTINCT FROM ARRAY['b3_anchor_sha256','b3_event_sha256','b3_sequence','bundle_sha256','companion_inventory','companion_root','custody_bundle_id','latest_source_reference','native_invocation_id','native_policy_sha256','native_started','original_started','proof_sha256','raw_inventory','raw_root','schema_version','scope','source_manifest_sha256','source_readback_complete']::text[]
   OR l->>'schema_version' IS DISTINCT FROM 'ctcc.native_history_member_linkage.v1'
   OR l->'scope' IS DISTINCT FROM jsonb_build_array(NEW.environment,NEW.account_id,NEW.settlement_currency)
   OR l->'b3_sequence' IS DISTINCT FROM to_jsonb(NEW.b3_sequence)
   OR l->>'b3_event_sha256' IS DISTINCT FROM NEW.b3_event_sha256
   OR l->'b3_anchor_sha256' IS DISTINCT FROM d->'anchor_sha256'
   OR l->'latest_source_reference' IS DISTINCT FROM d->'reference' THEN RAISE EXCEPTION 'account_history_partition_linkage'; END IF;
 FOREACH k IN ARRAY ARRAY['native_invocation_id','custody_bundle_id'] LOOP
   IF jsonb_typeof(l->k) IS DISTINCT FROM 'string' OR l->>k !~ '^[a-f0-9]{32}$' THEN RAISE EXCEPTION 'account_history_partition_linkage'; END IF;
 END LOOP;
 IF l->>'native_invocation_id' IS DISTINCT FROM NEW.native_invocation_id OR l->>'custody_bundle_id' IS DISTINCT FROM NEW.custody_bundle_id THEN RAISE EXCEPTION 'account_history_partition_linkage'; END IF;
 FOREACH k IN ARRAY ARRAY['bundle_sha256','proof_sha256','native_policy_sha256','source_manifest_sha256'] LOOP
   IF jsonb_typeof(l->k) IS DISTINCT FROM 'string' OR l->>k !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'account_history_partition_linkage'; END IF;
 END LOOP;
 root_a:=l->'raw_root'; root_b:=l->'companion_root';
 FOREACH stamp IN ARRAY ARRAY[root_a,root_b] LOOP
   IF jsonb_typeof(stamp) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(stamp) key) IS DISTINCT FROM ARRAY['device','inode','path']::text[]
     OR jsonb_typeof(stamp->'path') IS DISTINCT FROM 'string' OR length(stamp->>'path') NOT BETWEEN 1 AND 4096
     OR stamp->>'path' !~ '^(/|[A-Za-z]:[/\\])' OR stamp->>'path' ~ '(^|[/\\])\.\.([/\\]|$)'
     OR EXISTS(SELECT 1 FROM jsonb_each(stamp) WHERE key IN ('device','inode') AND (jsonb_typeof(value)<>'number' OR value::text !~ '^(0|[1-9][0-9]*)$' OR value::text::numeric>=340282366920938463463374607431768211456)) THEN
     RAISE EXCEPTION 'account_history_partition_root_locator'; END IF;
 END LOOP;
 IF root_a->>'path'=root_b->>'path' OR (root_a->'device'=root_b->'device' AND root_a->'inode'=root_b->'inode') THEN RAISE EXCEPTION 'account_history_partition_distinct_roots'; END IF;
 FOREACH k IN ARRAY ARRAY['raw_inventory','companion_inventory'] LOOP
   IF jsonb_typeof(l->k) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_each(l->k)) NOT BETWEEN 1 AND 8192 THEN RAISE EXCEPTION 'account_history_partition_inventory'; END IF;
   total:=0;
   FOR item IN SELECT key,value FROM jsonb_each(l->k) LOOP
     IF item.key='' OR item.key ~ '(^/|\\|:|(^|/)\.{1,2}(/|$)|(^|/)\.git(/|$)|(^|/)\.env)' OR jsonb_typeof(item.value) IS DISTINCT FROM 'array' OR jsonb_array_length(item.value)<>2
       OR jsonb_typeof(item.value->0) IS DISTINCT FROM 'number' OR item.value->>0 !~ '^[1-9][0-9]*$'
       OR (item.value->>0)::numeric>9223372036854775807 OR jsonb_typeof(item.value->1) IS DISTINCT FROM 'string' OR item.value->>1 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'account_history_partition_inventory'; END IF;
     total:=total+(item.value->>0)::numeric;
   END LOOP;
   IF (SELECT count(*) FROM jsonb_object_keys(l->k))<>(SELECT count(DISTINCT lower(key)) FROM jsonb_object_keys(l->k) key)
     OR total>(CASE WHEN k='raw_inventory' THEN 73531392 ELSE 4718592 END) THEN RAISE EXCEPTION 'account_history_partition_inventory'; END IF;
 END LOOP;
 IF NOT (l->'raw_inventory' ?& ARRAY['source.bundle.json','accepted.json','attempt.claim.json']) OR l->'raw_inventory'->'source.bundle.json'->>1 IS DISTINCT FROM l->>'bundle_sha256' THEN RAISE EXCEPTION 'account_history_partition_custody_locator'; END IF;
 previous_stamp:=NULL;
 FOREACH k IN ARRAY ARRAY['original_started','native_started','source_readback_complete'] LOOP
   stamp:=l->k;
   IF jsonb_typeof(stamp) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(stamp) key) IS DISTINCT FROM ARRAY['monotonic_ns','utc_ns']::text[]
     OR EXISTS(SELECT 1 FROM jsonb_each(stamp) WHERE jsonb_typeof(value)<>'number' OR value::text !~ '^[1-9][0-9]*$' OR value::text::numeric>9223372036854775807)
     OR (previous_stamp IS NOT NULL AND ((stamp->>'utc_ns')::numeric<(previous_stamp->>'utc_ns')::numeric OR (stamp->>'monotonic_ns')::numeric<(previous_stamp->>'monotonic_ns')::numeric)) THEN
     RAISE EXCEPTION 'account_history_partition_clock'; END IF;
   previous_stamp:=stamp;
 END LOOP;
 expected:=jsonb_build_object('schema_version','ctcc.native_history_member_registration.v1','policy_sha256','1793b33a09a48d494c6e8921d5248dfd93ce582d424bfa85952aad068534a982','scope',jsonb_build_array(NEW.environment,NEW.account_id,NEW.settlement_currency),
   'b3_sequence',NEW.b3_sequence,'b3_event_sha256',NEW.b3_event_sha256,'b3_anchor_sha256',d->'anchor_sha256','b3_receipt_sha256',d->'receipt_sha256',
   'source_reference',d->'reference','native_linkage_json',s->'native_linkage_json')||'{"account_complete": false, "account_history_finality": null, "account_revision": null, "arm_permission": false, "clear_stop_permission": false, "current_history_tail": null, "execution_authority": false, "funding_accrual": null, "historical_native_hwm": null, "loss_streak_seed": null, "source_authenticity_verified": false}'::jsonb;
 IF s IS DISTINCT FROM expected THEN RAISE EXCEPTION 'account_history_partition_registration'; END IF;
 RETURN NEW;
END

DECLARE entry record; b public.demo_account_observation_batches%ROWTYPE; m public.demo_account_history_native_members%ROWTYPE;
 d jsonb; a jsonb; s jsonb; previous jsonb:=NULL; expected jsonb; member jsonb; members jsonb; missing jsonb;
 prior_event text:=NULL; prior_anchor text:=NULL; previous_sha text:=NULL; root text; genesis_event text; genesis_anchor text;
 cumulative jsonb; counts jsonb; missing_total bigint:=0; overflow boolean:=false; source_policy text:=NULL;
 n bigint:=1; number bigint; k text; total bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'account_history_partition_immutable'; END IF;
 SELECT coalesce(sum(octet_length(checkpoint_json)),0)+octet_length(NEW.checkpoint_json) INTO total FROM public.demo_account_history_partition_checkpoints WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency;
 IF total>67108864 THEN RAISE EXCEPTION 'account_history_partition_cumulative_bound'; END IF;
 IF NEW.partition_number<>1+coalesce((SELECT max(partition_number) FROM public.demo_account_history_partition_checkpoints WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency),0)
   OR NEW.last_sequence<>(SELECT max(sequence) FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency) THEN
   RAISE EXCEPTION 'account_history_partition_checkpoint_head'; END IF;
 cumulative:=jsonb_build_object('source_facts_through_sequence',0,'coverage_through_sequence',0,'unresolved_findings_through_sequence',0);
 root:=encode(sha256(convert_to(public.account_history_partition_v1_encode(jsonb_build_array('1793b33a09a48d494c6e8921d5248dfd93ce582d424bfa85952aad068534a982',encode(sha256(convert_to('["demo","'||NEW.account_id||'","USDT"]','UTF8')),'hex'),'original_B3_partition_genesis')),'UTF8')),'hex');
 FOR entry IN SELECT partition_number,checkpoint_sha256,checkpoint_json FROM public.demo_account_history_partition_checkpoints WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency
   UNION ALL SELECT NEW.partition_number,NEW.checkpoint_sha256,NEW.checkpoint_json ORDER BY partition_number LOOP
   IF entry.partition_number<>n OR encode(sha256(convert_to(entry.checkpoint_json,'UTF8')),'hex')<>entry.checkpoint_sha256 THEN RAISE EXCEPTION 'account_history_partition_checkpoint_gap'; END IF;
   s:=public.account_history_partition_v1_json(entry.checkpoint_json);
   IF jsonb_typeof(s->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'members')<>32 THEN RAISE EXCEPTION 'account_history_partition_exact32'; END IF;
   missing:='[]'::jsonb; members:='[]'::jsonb;
   FOR number IN SELECT pg_catalog.generate_series(32*(n-1)+1,32*n) LOOP
     member:=s->'members'->((number-1)%32)::integer;
     SELECT * INTO b FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency AND sequence=number;
     IF b.sequence IS NULL OR member->>'b3_document_json' IS DISTINCT FROM b.document_json THEN RAISE EXCEPTION 'account_history_partition_member_source'; END IF;
     d:=public.account_history_partition_v1_json(b.document_json); a:=public.account_history_partition_v1_json(d->>'anchor_json');
     IF encode(sha256(convert_to(b.document_json,'UTF8')),'hex')<>b.event_sha256 OR d->'sequence' IS DISTINCT FROM to_jsonb(number)
       OR d->>'previous_sha256' IS DISTINCT FROM prior_event OR a->>'previous_anchor_sha256' IS DISTINCT FROM prior_anchor
       OR a->'through_sequence' IS DISTINCT FROM to_jsonb(number) OR a->'previous_sequence' IS DISTINCT FROM to_jsonb(number-1)
       OR a->>'previous_event_sha256' IS DISTINCT FROM prior_event OR d->>'anchor_sha256' IS DISTINCT FROM encode(sha256(convert_to(d->>'anchor_json','UTF8')),'hex')
       OR d->'account_complete' IS DISTINCT FROM 'false'::jsonb OR d->'execution_authority' IS DISTINCT FROM 'false'::jsonb
       OR d->>'admission' IS DISTINCT FROM 'DENY' THEN RAISE EXCEPTION 'account_history_partition_global_source_chain'; END IF;
     IF number=1 THEN source_policy:=d->>'policy_sha256'; genesis_event:=b.event_sha256; genesis_anchor:=d->>'anchor_sha256'; END IF;
     IF d->>'policy_sha256' IS DISTINCT FROM source_policy OR a->>'policy_sha256' IS DISTINCT FROM source_policy
       OR d->>'scope_sha256' IS DISTINCT FROM encode(sha256(convert_to('["demo","'||NEW.account_id||'","USDT"]','UTF8')),'hex')
       OR a->'scope_sha256' IS DISTINCT FROM d->'scope_sha256' THEN RAISE EXCEPTION 'account_history_partition_source_policy'; END IF;
     counts:=jsonb_build_object('source_facts_through_sequence',coalesce((d->>'source_membership_count')::bigint,-1)+(cumulative->>'source_facts_through_sequence')::bigint,
       'coverage_through_sequence',coalesce((d->>'coverage_membership_count')::bigint,-1)+(cumulative->>'coverage_through_sequence')::bigint,
       'unresolved_findings_through_sequence',coalesce((d->>'finding_membership_count')::bigint,-1)+(cumulative->>'unresolved_findings_through_sequence')::bigint);
     FOREACH k IN ARRAY ARRAY['source_facts_through_sequence','coverage_through_sequence','unresolved_findings_through_sequence'] LOOP
       IF a->k IS DISTINCT FROM counts->k OR jsonb_typeof(a->k) IS DISTINCT FROM 'number' OR a->>k !~ '^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'account_history_partition_cumulative_counts'; END IF;
     END LOOP;
     IF a->'required_proof_budget_exceeded' NOT IN ('true'::jsonb,'false'::jsonb) THEN RAISE EXCEPTION 'account_history_partition_overflow_unknown'; END IF;
     overflow:=overflow OR (a->>'required_proof_budget_exceeded')::boolean;
     SELECT * INTO m FROM public.demo_account_history_native_members WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency AND b3_sequence=number;
     IF m.b3_sequence IS NULL THEN
       IF member->'native_registration_json' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'account_history_partition_registration_unknown'; END IF;
       missing:=missing||to_jsonb(number); missing_total:=missing_total+1;
     ELSE
       IF member->>'native_registration_json' IS DISTINCT FROM m.registration_json OR m.b3_event_sha256<>b.event_sha256
         OR encode(sha256(convert_to(m.registration_json,'UTF8')),'hex')<>m.registration_sha256 THEN RAISE EXCEPTION 'account_history_partition_registration_changed'; END IF;
     END IF;
     root:=encode(sha256(convert_to(public.account_history_partition_v1_encode(jsonb_build_array(root,number,b.event_sha256,d->'anchor_sha256',d->'receipt_sha256',d->'source_membership_sha256',d->'coverage_membership_sha256',d->'finding_membership_sha256',m.registration_sha256)),'UTF8')),'hex');
     members:=members||jsonb_build_object('b3_document_json',b.document_json,'native_registration_json',m.registration_json);
     prior_event:=b.event_sha256; prior_anchor:=d->>'anchor_sha256'; cumulative:=counts;
   END LOOP;
   expected:=jsonb_build_object('schema_version','ctcc.native_history_partition_checkpoint.v1','policy_sha256','1793b33a09a48d494c6e8921d5248dfd93ce582d424bfa85952aad068534a982','b3_policy_sha256',source_policy,'scope',jsonb_build_array(NEW.environment,NEW.account_id,NEW.settlement_currency),
     'partition_number',n,'first_sequence',32*(n-1)+1,'last_sequence',32*n,'member_count',32,'previous_checkpoint_sha256',previous_sha,
     'previous_terminal_event_sha256',previous->'terminal_event_sha256','previous_terminal_anchor_sha256',previous->'terminal_anchor_sha256',
     'genesis_event_sha256',genesis_event,'genesis_anchor_sha256',genesis_anchor,'terminal_event_sha256',prior_event,'terminal_anchor_sha256',prior_anchor,
     'ordered_membership_sha256',root,'cumulative_counts',cumulative,'missing_native_registration_sequences',missing,'native_registration_count',32-jsonb_array_length(missing),
     'missing_native_registrations_through_sequence',missing_total,'required_proof_budget_exceeded',overflow,'members',members)||'{"account_complete": false, "account_history_finality": null, "account_revision": null, "arm_permission": false, "clear_stop_permission": false, "current_history_tail": null, "execution_authority": false, "funding_accrual": null, "historical_native_hwm": null, "loss_streak_seed": null, "source_authenticity_verified": false}'::jsonb;
   IF s IS DISTINCT FROM expected THEN RAISE EXCEPTION 'account_history_partition_checkpoint_changed'; END IF;
   previous:=expected; previous_sha:=entry.checkpoint_sha256; n:=n+1;
 END LOOP;
 IF NEW.previous_checkpoint_sha256 IS DISTINCT FROM previous->>'previous_checkpoint_sha256'
   OR NEW.terminal_event_sha256 IS DISTINCT FROM prior_event
   OR NEW.first_sequence<>(previous->>'first_sequence')::bigint OR NEW.last_sequence<>(previous->>'last_sequence')::bigint THEN
   RAISE EXCEPTION 'account_history_partition_checkpoint_columns'; END IF;
 RETURN NEW;
END

DECLARE b public.demo_account_observation_batches%ROWTYPE; current_cp public.demo_account_history_partition_checkpoints%ROWTYPE;
 s jsonb; l jsonb; v jsonb; existing text;
BEGIN
 PERFORM public.account_history_partition_v1_lock(p_environment,p_account_id,p_currency,p_control_revision,p_account_revision,p_ledger_revision,p_expires);
 IF p_control_revision IS NULL OR p_account_revision IS NULL OR p_ledger_revision IS NULL OR p_control_revision<1 OR p_account_revision<0 THEN RAISE EXCEPTION 'account_history_partition_fence_invalid'; END IF;
 SELECT * INTO b FROM public.demo_account_observation_batches WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency ORDER BY sequence DESC LIMIT 1;
 IF b.sequence IS NULL OR b.event_sha256 IS DISTINCT FROM p_expected_b3_sha THEN RAISE EXCEPTION 'account_history_partition_head_changed'; END IF;
 SELECT * INTO current_cp FROM public.demo_account_history_partition_checkpoints WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency ORDER BY partition_number DESC LIMIT 1;
 IF current_cp.checkpoint_sha256 IS DISTINCT FROM p_previous_checkpoint_sha THEN RAISE EXCEPTION 'account_history_partition_checkpoint_cas'; END IF;
 s:=public.account_history_partition_v1_json(p_registration); l:=public.account_history_partition_v1_json(s->>'native_linkage_json');
 SELECT registration_json INTO existing FROM public.demo_account_history_native_members WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency AND b3_sequence=b.sequence;
 IF existing IS NOT NULL THEN
   IF existing<>p_registration THEN RAISE EXCEPTION 'account_history_partition_registration_conflict'; END IF;
   RAISE EXCEPTION 'account_history_partition_already_recorded_no_reissue';
 END IF;
 INSERT INTO public.demo_account_history_native_members(environment,account_id,settlement_currency,b3_sequence,capture_id,source_sequence,b3_event_sha256,b3_document_json,registration_sha256,registration_json,native_invocation_id,custody_bundle_id)
   VALUES(p_environment,p_account_id,p_currency,b.sequence,b.capture_id,b.source_sequence,b.event_sha256,b.document_json,encode(sha256(convert_to(p_registration,'UTF8')),'hex'),p_registration,l->>'native_invocation_id',l->>'custody_bundle_id');
 IF p_checkpoint IS NOT NULL THEN
   v:=public.account_history_partition_v1_json(p_checkpoint);
   INSERT INTO public.demo_account_history_partition_checkpoints(environment,account_id,settlement_currency,partition_number,first_sequence,last_sequence,terminal_event_sha256,previous_checkpoint_sha256,checkpoint_sha256,checkpoint_json)
     VALUES(p_environment,p_account_id,p_currency,(v->>'partition_number')::bigint,(v->>'first_sequence')::bigint,(v->>'last_sequence')::bigint,v->>'terminal_event_sha256',v->>'previous_checkpoint_sha256',encode(sha256(convert_to(p_checkpoint,'UTF8')),'hex'),p_checkpoint);
 END IF;
 -- Immediate row guards plus deferred immutable-source pair checks both run;
 -- commit uncertainty is never converted into a retry or a replacement row.
 IF p_expires<=clock_timestamp() THEN RAISE EXCEPTION 'account_history_partition_expired_before_commit'; END IF;
 RETURN encode(sha256(convert_to(p_registration,'UTF8')),'hex');
END

DECLARE result jsonb; total numeric; h public.demo_account_observation_batches%ROWTYPE;
BEGIN
 PERFORM public.account_history_partition_v1_lock(p_environment,p_account_id,p_currency,NULL,NULL,NULL,NULL);
 SELECT coalesce(sum(octet_length(document_json)),0) INTO total FROM public.demo_account_observation_batches WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency;
 total:=total+coalesce((SELECT sum(octet_length(registration_json)) FROM public.demo_account_history_native_members WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),0)
   +coalesce((SELECT sum(octet_length(checkpoint_json)) FROM public.demo_account_history_partition_checkpoints WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),0);
 IF total>67108864 THEN RAISE EXCEPTION 'account_history_partition_read_bound'; END IF;
 SELECT * INTO h FROM public.demo_account_observation_batches WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency ORDER BY sequence DESC LIMIT 1;
 SELECT jsonb_build_object('scope',jsonb_build_array(p_environment,p_account_id,p_currency),'head_sequence',h.sequence,'head_sha256',h.event_sha256,
   'control_revision',(SELECT control_revision FROM public.demo_account_controls WHERE environment=p_environment AND account_id=p_account_id),
   'account_revision',(SELECT account_revision FROM public.qualification_account_scopes WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),
   'ledger_revision',(SELECT ledger_revision FROM public.qualification_account_scopes WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),'backend_pid',pg_backend_pid(),'transaction_id',pg_current_xact_id()::text,
   'members',coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',b3_sequence,'record_json',registration_json,'record_sha256',registration_sha256,'recorded_at',recorded_at) ORDER BY b3_sequence) FROM public.demo_account_history_native_members WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),'[]'::jsonb),
   'checkpoints',coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',partition_number,'record_json',checkpoint_json,'record_sha256',checkpoint_sha256,'recorded_at',recorded_at) ORDER BY partition_number) FROM public.demo_account_history_partition_checkpoints WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),'[]'::jsonb),
   'b3_documents',coalesce((SELECT jsonb_agg(document_json ORDER BY sequence) FROM public.demo_account_observation_batches WHERE environment=p_environment AND account_id=p_account_id AND settlement_currency=p_currency),'[]'::jsonb)) INTO result;
 RETURN result;
END

BEGIN
 IF TG_TABLE_NAME='demo_account_history_native_members' THEN
   IF NOT EXISTS(SELECT 1 FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency AND sequence=NEW.b3_sequence AND event_sha256=NEW.b3_event_sha256 AND document_json=NEW.b3_document_json) THEN
     RAISE EXCEPTION 'account_history_partition_deferred_source_changed'; END IF;
 ELSE
   IF NOT EXISTS(SELECT 1 FROM public.demo_account_observation_batches WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency AND sequence=NEW.last_sequence AND event_sha256=NEW.terminal_event_sha256) THEN
     RAISE EXCEPTION 'account_history_partition_deferred_source_changed'; END IF;
 END IF;
 RETURN NEW;
END

DECLARE d jsonb; s jsonb; scan jsonb; h public.demo_controlled_writer_coverage_scopes%ROWTYPE;
 j public.demo_controlled_writer_coverage_journal%ROWTYPE;
 c public.demo_account_controls%ROWTYPE; q public.qualification_account_scopes%ROWTYPE;
 k text; before_ns numeric; start_ns numeric; before_mono numeric; start_mono numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'prospective_cutover_immutable'; END IF;
 d:=public.account_history_partition_v1_json(NEW.record_json);
 IF (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(d) key)
   IS DISTINCT FROM ARRAY['account_complete','account_id','account_revision','account_revision_published','active_event_sha256','active_journal_sequence','active_state_sha256','audit_sha256','control_event_sha256','control_owner_epoch','control_revision','control_state_sha256','coverage_start','credential_session_sha256','cutover_id','environment','epoch_id','event_keys_sha256','execution_authority','g6_qualified','generation','historical_event_history_complete','journal_scan_json','journal_scan_sha256','ledger_revision','manifest_sha256','namespace_history_complete','namespace_policy','post_active_readback','record_kind','rows_sha256','schema_version','scope_rule','settlement_currency','source_bundle_sha256','source_current_receipt_sha256','source_native_proof_sha256','source_native_readback_sha256','transitions_sha256','writer_inventory_sha256']::text[] THEN RAISE EXCEPTION 'prospective_cutover_shape'; END IF;
 IF d->>'schema_version' IS DISTINCT FROM 'ctcc.prospective_ctcc_event_cutover.v2'
   OR d->>'environment' IS DISTINCT FROM NEW.environment
   OR d->>'account_id' IS DISTINCT FROM NEW.account_id
   OR d->>'settlement_currency' IS DISTINCT FROM NEW.settlement_currency
   OR d->>'epoch_id' IS DISTINCT FROM NEW.epoch_id
   OR d->'active_journal_sequence' IS DISTINCT FROM to_jsonb(NEW.active_journal_sequence)
   OR d->>'active_event_sha256' IS DISTINCT FROM NEW.active_event_sha256
   OR d->>'cutover_id' IS DISTINCT FROM NEW.cutover_id
   OR d->>'namespace_policy' IS DISTINCT FROM 'ctcc-prospective-reservation-namespace-v1'
   OR d->>'scope_rule' IS DISTINCT FROM 'original_trigger_candle_open_strictly_after_start'
   OR d->>'record_kind' IS DISTINCT FROM 'prospective_cutover_not_g6_or_order_authority' THEN
   RAISE EXCEPTION 'prospective_cutover_binding'; END IF;
 FOREACH k IN ARRAY ARRAY['account_complete','account_revision_published','namespace_history_complete','historical_event_history_complete','g6_qualified','execution_authority'] LOOP
   IF d->k IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'prospective_cutover_authority_claim'; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['generation','active_journal_sequence','control_owner_epoch','control_revision','account_revision','ledger_revision'] LOOP
   IF jsonb_typeof(d->k) IS DISTINCT FROM 'number' OR d->>k !~ '^(0|[1-9][0-9]{0,18})$'
    OR (d->>k)::numeric>9223372036854775807
    OR (k NOT IN ('account_revision','ledger_revision') AND (d->>k)::numeric<1) THEN
     RAISE EXCEPTION 'prospective_cutover_revision'; END IF;
 END LOOP;
 IF (d->>'ledger_revision')::bigint<(d->>'account_revision')::bigint
  OR jsonb_typeof(d->'journal_scan_json') IS DISTINCT FROM 'string'
  OR octet_length(d->>'journal_scan_json') NOT BETWEEN 1 AND 4096
  OR encode(sha256(convert_to(d->>'journal_scan_json','UTF8')),'hex') IS DISTINCT FROM d->>'journal_scan_sha256' THEN
   RAISE EXCEPTION 'prospective_cutover_scan_binding'; END IF;
 scan:=public.account_history_partition_v1_json(d->>'journal_scan_json');
 IF scan->>'schema_version' IS DISTINCT FROM 'ctcc.consumed_event_journal_inspection.v1'
  OR scan->'db_journal_row_chain_verified' IS DISTINCT FROM 'true'::jsonb
  OR scan->>'admission' IS DISTINCT FROM 'DENY' THEN RAISE EXCEPTION 'prospective_cutover_scan_binding'; END IF;
 FOREACH k IN ARRAY ARRAY['db_journal_complete','external_event_history_complete','source_authenticity_verified','execution_authority'] LOOP
   IF scan->k IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'prospective_cutover_scan_binding'; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['account_revision','ledger_revision','event_keys_sha256','rows_sha256','transitions_sha256'] LOOP
   IF scan->k IS DISTINCT FROM d->k THEN RAISE EXCEPTION 'prospective_cutover_scan_binding'; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['active_event_sha256','active_state_sha256','audit_sha256','control_event_sha256','control_state_sha256','credential_session_sha256','cutover_id','event_keys_sha256','journal_scan_sha256','manifest_sha256','rows_sha256','source_bundle_sha256','source_current_receipt_sha256','source_native_proof_sha256','source_native_readback_sha256','transitions_sha256','writer_inventory_sha256'] LOOP
   IF jsonb_typeof(d->k) IS DISTINCT FROM 'string' OR d->>k !~ '^[a-f0-9]{64}$' THEN
     RAISE EXCEPTION 'prospective_cutover_digest'; END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['post_active_readback','coverage_start'] LOOP
   IF jsonb_typeof(d->k) IS DISTINCT FROM 'object'
     OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(d->k) key)
      IS DISTINCT FROM ARRAY['monotonic_ns','utc_ns']::text[]
     OR jsonb_typeof(d->k->'utc_ns') IS DISTINCT FROM 'number'
     OR jsonb_typeof(d->k->'monotonic_ns') IS DISTINCT FROM 'number'
     OR d->k->>'utc_ns' !~ '^(0|[1-9][0-9]{0,19})$'
     OR d->k->>'monotonic_ns' !~ '^(0|[1-9][0-9]{0,19})$'
     OR (d->k->>'utc_ns')::numeric>32503680000000000000
     OR (d->k->>'monotonic_ns')::numeric>32503680000000000000 THEN
     RAISE EXCEPTION 'prospective_cutover_stamp'; END IF;
 END LOOP;
 before_ns:=(d->'post_active_readback'->>'utc_ns')::numeric;
 start_ns:=(d->'coverage_start'->>'utc_ns')::numeric;
 before_mono:=(d->'post_active_readback'->>'monotonic_ns')::numeric;
 start_mono:=(d->'coverage_start'->>'monotonic_ns')::numeric;
 IF start_ns<=before_ns OR start_mono<=before_mono THEN
   RAISE EXCEPTION 'prospective_cutover_start_not_after_readback'; END IF;
 NEW.coverage_start_at:=TIMESTAMPTZ 'epoch'+(ceil(start_ns/1000)::text||' microseconds')::interval;
 NEW.recorded_at:=clock_timestamp();
 IF NEW.coverage_start_at>NEW.recorded_at THEN RAISE EXCEPTION 'prospective_cutover_future_start'; END IF;
 IF NEW.cutover_id<>encode(sha256(convert_to(public.account_history_partition_v1_encode(
   jsonb_build_array(NEW.environment,NEW.account_id,NEW.epoch_id,NEW.active_event_sha256)),'UTF8')),'hex') THEN
   RAISE EXCEPTION 'prospective_cutover_identity'; END IF;
 SELECT * INTO c FROM public.demo_account_controls WHERE environment=NEW.environment AND account_id=NEW.account_id FOR UPDATE;
 SELECT * INTO h FROM public.demo_controlled_writer_coverage_scopes WHERE environment=NEW.environment AND account_id=NEW.account_id FOR UPDATE;
 SELECT * INTO q FROM public.qualification_account_scopes WHERE environment=NEW.environment AND account_id=NEW.account_id AND settlement_currency=NEW.settlement_currency FOR UPDATE;
 SELECT * INTO j FROM public.demo_controlled_writer_coverage_journal WHERE environment=NEW.environment AND account_id=NEW.account_id AND journal_sequence=NEW.active_journal_sequence;
 s:=j.state_json::jsonb;
 IF c.account_id IS NULL OR h.account_id IS NULL OR q.account_id IS NULL OR j.account_id IS NULL
   OR h.state<>'active' OR j.action<>'active' OR h.epoch_id<>NEW.epoch_id
   OR h.journal_sequence<>NEW.active_journal_sequence OR h.journal_sha256<>NEW.active_event_sha256
   OR j.event_sha256<>NEW.active_event_sha256 OR h.state_json<>j.state_json
   OR j.recorded_at> TIMESTAMPTZ 'epoch'+(ceil(before_ns/1000)::text||' microseconds')::interval
   OR (s->'transition_stamp'->>'monotonic_ns')::numeric>before_mono
   OR d->'generation' IS DISTINCT FROM to_jsonb(j.generation)
   OR d->>'active_state_sha256' IS DISTINCT FROM j.state_sha256
   OR d->>'audit_sha256' IS DISTINCT FROM j.audit_sha256 THEN
   RAISE EXCEPTION 'prospective_cutover_active_changed'; END IF;
 FOREACH k IN ARRAY ARRAY['credential_session_sha256','writer_inventory_sha256','source_bundle_sha256',
   'source_current_receipt_sha256','source_native_proof_sha256','source_native_readback_sha256',
   'control_owner_epoch','control_revision','control_event_sha256','control_state_sha256'] LOOP
   IF d->k IS DISTINCT FROM s->k THEN RAISE EXCEPTION 'prospective_cutover_source_changed'; END IF;
 END LOOP;
 IF d->>'manifest_sha256' IS DISTINCT FROM s->>'deployed_manifest_sha256'
   OR NOT c.emergency_stop OR c.arm_request_id IS NOT NULL
   OR c.owner_epoch IS DISTINCT FROM (d->>'control_owner_epoch')::bigint
   OR c.control_revision IS DISTINCT FROM (d->>'control_revision')::bigint
   OR c.state_sha256 IS DISTINCT FROM d->>'control_state_sha256'
   OR c.lease_until<=clock_timestamp()
   OR (s->>'source_current_expires_at')::timestamptz<=clock_timestamp()
   OR q.account_revision IS DISTINCT FROM (d->>'account_revision')::bigint
   OR q.ledger_revision IS DISTINCT FROM (d->>'ledger_revision')::bigint
   OR NOT EXISTS(SELECT 1 FROM public.demo_control_journal x WHERE x.environment=c.environment
    AND x.account_id=c.account_id AND x.control_revision=c.control_revision
    AND x.event_sha256=d->>'control_event_sha256')
   OR EXISTS(SELECT 1 FROM public.qualification_reservations r WHERE r.environment=NEW.environment
    AND r.account_id=NEW.account_id AND r.state<>'reconciled_flat') THEN
   RAISE EXCEPTION 'prospective_cutover_control_or_holds_changed'; END IF;
 RETURN NEW;
END

DECLARE d jsonb;
BEGIN
 IF p_environment IS DISTINCT FROM 'demo' OR p_account_id !~ '^[0-9]{1,32}$'
   OR p_epoch_id !~ '^[a-f0-9]{32}$' OR octet_length(p_raw) NOT BETWEEN 1 AND 16384 THEN
   RAISE EXCEPTION 'prospective_cutover_input'; END IF;
 IF current_user=session_user OR current_setting('role')<>'none'
   OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND
    (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls))
   OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname<>session_user AND pg_has_role(session_user,r.oid,'MEMBER'))
   OR has_schema_privilege(session_user,'public','CREATE')
   OR has_database_privilege(session_user,current_database(),'CREATE')
   OR has_table_privilege(session_user,'public.demo_controlled_writer_coverage_cutovers','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') THEN
   RAISE EXCEPTION 'prospective_cutover_role_denied'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('TimeZone')<>'UTC'
   OR current_setting('synchronous_commit')<>'on' OR current_setting('session_replication_role')<>'origin'
   OR pg_is_in_recovery() OR current_setting('fsync')<>'on' OR current_setting('full_page_writes')<>'on' THEN
   RAISE EXCEPTION 'prospective_cutover_session_denied'; END IF;
 PERFORM pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
 PERFORM 1 FROM public.demo_account_controls WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
 PERFORM 1 FROM public.demo_controlled_writer_coverage_scopes WHERE environment=p_environment AND account_id=p_account_id FOR UPDATE;
 PERFORM 1 FROM public.qualification_account_scopes WHERE environment=p_environment AND account_id=p_account_id ORDER BY settlement_currency FOR UPDATE;
 LOCK TABLE public.qualification_account_scopes, public.qualification_reservations,
  public.qualification_reservation_transitions IN SHARE MODE NOWAIT;
 LOCK TABLE public.demo_controlled_writer_coverage_scopes, public.demo_controlled_writer_coverage_journal,
  public.demo_controlled_writer_coverage_cutovers IN ROW EXCLUSIVE MODE NOWAIT;
 d:=public.account_history_partition_v1_json(convert_from(p_raw,'UTF8'));
 IF d->>'environment' IS DISTINCT FROM p_environment OR d->>'account_id' IS DISTINCT FROM p_account_id
   OR d->>'epoch_id' IS DISTINCT FROM p_epoch_id THEN RAISE EXCEPTION 'prospective_cutover_binding'; END IF;
 INSERT INTO public.demo_controlled_writer_coverage_cutovers VALUES(
  p_environment,p_account_id,d->>'settlement_currency',p_epoch_id,(d->>'active_journal_sequence')::bigint,
  d->>'active_event_sha256',d->>'cutover_id',encode(sha256(p_raw),'hex'),convert_from(p_raw,'UTF8'),
  clock_timestamp(),clock_timestamp());
 RETURN encode(sha256(p_raw),'hex');
END

DECLARE r public.demo_controlled_writer_coverage_cutovers%ROWTYPE;
BEGIN
 IF p_environment IS DISTINCT FROM 'demo' OR p_account_id !~ '^[0-9]{1,32}$'
   OR p_epoch_id !~ '^[a-f0-9]{32}$' OR p_expected !~ '^[a-f0-9]{64}$' THEN
   RAISE EXCEPTION 'prospective_cutover_read_input'; END IF;
 PERFORM pg_advisory_xact_lock(('x'||substr(encode(pg_catalog.sha256(pg_catalog.convert_to('ctcc-qualification-account-v1','UTF8')||decode('00','hex')||pg_catalog.convert_to(p_environment,'UTF8')||decode('00','hex')||pg_catalog.convert_to(p_account_id,'UTF8')),'hex'),1,16))::bit(64)::bigint);
 LOCK TABLE public.demo_controlled_writer_coverage_cutovers IN SHARE MODE NOWAIT;
 SELECT * INTO r FROM public.demo_controlled_writer_coverage_cutovers WHERE environment=p_environment
  AND account_id=p_account_id AND epoch_id=p_epoch_id;
 IF r.account_id IS NULL OR r.record_sha256 IS DISTINCT FROM p_expected THEN
   RAISE EXCEPTION 'prospective_cutover_readback'; END IF;
 RETURN jsonb_build_object('record_json',r.record_json,'record_sha256',r.record_sha256,
  'recorded_at',r.recorded_at,'coverage_start_at',r.coverage_start_at);
END

